window.__AtlasPayload=window.__AtlasPayload||{};window.__AtlasPayload["prod-dyna-diag"]={"pkg":{"id":"prod-dyna-diag","sceneId":"pr1","methods":["cv","ts"],"title":"抽油机井示功图智能工况诊断与检泵排序","version":"1.0.0","updated":"2026-11-01","tabs":{"background":{"label":"专业背景","lede":"游梁式抽油机（俗称“磕头机”）占我国陆上油田人工举升井的 **80% 以上**。由于深井泵工作在地下 1500–2500 米的高温高压盲区，工程师无法直接观察井下阀门与液面，只能靠井口光杆传感器绘制的**示功图（载荷 P — 位移 S 闭合环）**充当井下“心电图”。然而一个中型采油厂每天产生超过 **36 万张**示功图，千米弹性抽油杆的谐波振动又会严重扭曲地面波形；用物理反演结合计算机视觉与频域特征自动识别工况、排序检泵工单，是油田降本稳产的核心抓手。","judge":[{"label":"数据形态","value":"闭合载荷—位移环","desc":"单冲程 P-S 周期序列 + 栅格环图"},{"label":"标注成本","value":"中偏高","desc":"需结合修井检泵拆解记录确权"},{"label":"可见收益","value":"极高","desc":"秒级捕获断杆、减少 34% 盲目检泵"},{"label":"工程难度","value":"中","desc":"深井杆柱振动剥离与复合工况解耦"}],"sections":[{"no":1,"en":"","title":"当前做法与问题","html":"<p>游梁式抽油机通过地面曲柄连杆带动驴头上下往复，经 <b>1500–2500 米长的抽油杆柱</b>驱动井下深井泵柱塞。深井泵内设两个单向球阀：随柱塞移动的<b>游动阀（Traveling Valve, TV，又称出油阀）</b>和固定在泵筒底部的<b>固定阀（Standing Valve, SV，又称进油阀）</b>。一个完整冲程分为四个力学阶段：<b>A→B 弹性加载</b>（双阀紧闭，液柱重量从油管转移到抽油杆）、<b>B→C 上冲程排液</b>（SV 吸液开启、TV 承压关闭，光杆提液上行）、<b>C→D 换向卸载</b>（上死点换向，双阀暂闭，杆柱弹性回缩卸载）、<b>D→A 下冲程充液</b>（泵内增压顶开 TV，柱塞下行穿过液柱）。理想状态下，井下功图呈标准的<b>平行四边形</b>，环内包络面积正比于单冲程排液做功。</p>\n<div class=\"figure\">\n<svg viewBox=\"0 0 760 350\" width=\"100%\" role=\"img\" aria-label=\"游梁式抽油机—深井泵四冲程循环物理过程与理想平行四边形示功图对照\">\n  <defs>\n    <linearGradient id=\"pdd-f1-sky\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#f7f5f0\"/>\n      <stop offset=\"100%\" stop-color=\"#f0ede5\"/>\n    </linearGradient>\n    <linearGradient id=\"pdd-f1-oil\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#3a6ea5\" stop-opacity=\"0.32\"/>\n      <stop offset=\"100%\" stop-color=\"#12615a\" stop-opacity=\"0.65\"/>\n    </linearGradient>\n    <marker id=\"pdd-arr-g\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\">\n      <path d=\"M0,1 L9,5 L0,9 Z\" fill=\"#12615a\"/>\n    </marker>\n    <marker id=\"pdd-arr-a\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\">\n      <path d=\"M0,1 L9,5 L0,9 Z\" fill=\"#c27a2c\"/>\n    </marker>\n    <marker id=\"pdd-arr-r\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\">\n      <path d=\"M0,1 L9,5 L0,9 Z\" fill=\"#b4483c\"/>\n    </marker>\n  </defs>\n\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"350\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <line x1=\"296\" y1=\"12\" x2=\"296\" y2=\"292\" stroke=\"#e7e3da\" stroke-dasharray=\"4,3\"/>\n\n  <!-- 左侧：游梁式抽油机与 2000m 深井泵结构剖面 (x: 12..288) -->\n  <text x=\"150\" y=\"24\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"12\" font-weight=\"700\">① 地面游梁抽油机 — 井下深井泵耦合系统</text>\n\n  <!-- 地面线 -->\n  <rect x=\"16\" y=\"34\" width=\"268\" height=\"72\" rx=\"4\" fill=\"url(#pdd-f1-sky)\" stroke=\"#e7e3da\"/>\n  <line x1=\"16\" y1=\"106\" x2=\"284\" y2=\"106\" stroke=\"#b9a27c\" stroke-width=\"2.5\"/>\n  <text x=\"24\" y=\"101\" fill=\"#737c83\" font-size=\"9.5\">井口地面 (0 m)</text>\n\n  <!-- 支架 (Samson Post) 与游梁 (Walking Beam) + 驴头 (Horsehead) -->\n  <polygon points=\"168,106 186,58 204,106\" fill=\"none\" stroke=\"#424a50\" stroke-width=\"2\"/>\n  <line x1=\"112\" y1=\"54\" x2=\"246\" y2=\"62\" stroke=\"#15191c\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n  <circle cx=\"186\" cy=\"58\" r=\"3.5\" fill=\"#c27a2c\"/>\n  <!-- 驴头弧面 -->\n  <path d=\"M112,42 Q98,56 112,72 L118,54 Z\" fill=\"#12615a\"/>\n  <text x=\"148\" y=\"47\" fill=\"#15191c\" font-size=\"9.5\" font-weight=\"600\">游梁与驴头</text>\n  <!-- 连杆与曲柄平衡重 -->\n  <line x1=\"244\" y1=\"62\" x2=\"254\" y2=\"92\" stroke=\"#424a50\" stroke-width=\"2\"/>\n  <circle cx=\"256\" cy=\"94\" r=\"10\" fill=\"#e4d6b8\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n  <text x=\"248\" y=\"80\" fill=\"#737c83\" font-size=\"9\">曲柄</text>\n\n  <!-- 光杆传感器 (Polished Rod Sensor) -->\n  <line x1=\"106\" y1=\"68\" x2=\"106\" y2=\"106\" stroke=\"#15191c\" stroke-width=\"2.2\"/>\n  <rect x=\"98\" y=\"80\" width=\"16\" height=\"12\" rx=\"2\" fill=\"#c27a2c\" stroke=\"#fff\" stroke-width=\"1\"/>\n  <text x=\"120\" y=\"90\" fill=\"#c27a2c\" font-size=\"9.5\" font-weight=\"700\">光杆载荷 P / 位移 S 传感器</text>\n\n  <!-- 井筒与地层剖面 (y: 108..286) -->\n  <rect x=\"16\" y=\"108\" width=\"268\" height=\"178\" fill=\"#f4efe4\"/>\n  <!-- 套管 (Casing) 与油管 (Tubing) -->\n  <rect x=\"76\" y=\"108\" width=\"60\" height=\"174\" fill=\"#ffffff\" stroke=\"#737c83\" stroke-width=\"1.6\"/>\n  <rect x=\"88\" y=\"108\" width=\"36\" height=\"162\" fill=\"#edf3f7\" stroke=\"#3a6ea5\" stroke-width=\"1.4\"/>\n  <!-- 液柱充填 -->\n  <rect x=\"90\" y=\"138\" width=\"32\" height=\"130\" fill=\"url(#pdd-f1-oil)\"/>\n  <line x1=\"76\" y1=\"138\" x2=\"136\" y2=\"138\" stroke=\"#3a6ea5\" stroke-width=\"1.2\" stroke-dasharray=\"2,2\"/>\n  <text x=\"142\" y=\"141\" fill=\"#3a6ea5\" font-size=\"9.5\" font-weight=\"600\">动液面 (沉没度)</text>\n\n  <!-- 2000m 弹性抽油杆柱 (Rod String) -->\n  <line x1=\"106\" y1=\"106\" x2=\"106\" y2=\"210\" stroke=\"#15191c\" stroke-width=\"2.4\" stroke-dasharray=\"8,2\"/>\n  <text x=\"142\" y=\"168\" fill=\"#15191c\" font-size=\"9.5\" font-weight=\"600\">抽油杆柱 (1500–2500m)</text>\n  <text x=\"142\" y=\"181\" fill=\"#737c83\" font-size=\"9\">弹性伸缩 + 粘滞摩擦阻尼</text>\n\n  <!-- 柱塞 (Plunger) 与游动阀 (TV) -->\n  <rect x=\"92\" y=\"210\" width=\"28\" height=\"22\" rx=\"2\" fill=\"#ffffff\" stroke=\"#12615a\" stroke-width=\"1.8\"/>\n  <circle cx=\"106\" cy=\"220\" r=\"4.5\" fill=\"#12615a\"/>\n  <text x=\"142\" y=\"222\" fill=\"#12615a\" font-size=\"9.5\" font-weight=\"700\">柱塞 + 游动阀 TV (出油阀)</text>\n\n  <!-- 固定阀 (SV) 与油层射孔段 -->\n  <polygon points=\"94,268 118,268 112,260 100,260\" fill=\"#424a50\"/>\n  <circle cx=\"106\" cy=\"256\" r=\"4.5\" fill=\"#c27a2c\"/>\n  <text x=\"142\" y=\"260\" fill=\"#c27a2c\" font-size=\"9.5\" font-weight=\"700\">固定阀 SV (进油阀)</text>\n  <text x=\"142\" y=\"276\" fill=\"#737c83\" font-size=\"9\">油层供液射孔段 (1800m)</text>\n  <text x=\"24\" y=\"200\" fill=\"#737c83\" font-size=\"9.5\">套管环空</text>\n\n  <!-- 右侧：四冲程循环与理想平行四边形 vs 实测地面功图 (x: 306..748) -->\n  <text x=\"528\" y=\"24\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"12\" font-weight=\"700\">② 四冲程载荷—位移闭合环（A加载 → B排液 → C卸载 → D充液）</text>\n\n  <!-- 坐标轴框 (x: 356..696, y: 42..246) -->\n  <rect x=\"356\" y=\"42\" width=\"340\" height=\"204\" rx=\"4\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n  <line x1=\"356\" y1=\"90\" x2=\"696\" y2=\"90\" stroke=\"#ece8df\" stroke-dasharray=\"3,3\"/>\n  <line x1=\"356\" y1=\"206\" x2=\"696\" y2=\"206\" stroke=\"#ece8df\" stroke-dasharray=\"3,3\"/>\n  <text x=\"350\" y=\"93\" text-anchor=\"end\" fill=\"#12615a\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">Pmax=Wr'+Wl</text>\n  <text x=\"350\" y=\"209\" text-anchor=\"end\" fill=\"#3a6ea5\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">Pmin=Wr'</text>\n  <text x=\"356\" y=\"262\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"9.5\">0 (下死点)</text>\n  <text x=\"526\" y=\"262\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"10.5\" font-weight=\"600\">光杆位移 S (m)</text>\n  <text x=\"690\" y=\"262\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"9.5\">S₀ (上死点)</text>\n\n  <!-- 理想理论平行四边形 A -> B -> C -> D -> A -->\n  <polygon points=\"376,206 424,90 672,90 624,206\" fill=\"rgba(18,97,90,0.08)\" stroke=\"#12615a\" stroke-width=\"2.2\"/>\n  <!-- 实测地面弹性振动示功图外环 (琥珀虚线) -->\n  <path d=\"M372,198 C388,130 408,68 430,78 C452,88 472,72 498,82 C535,92 585,78 674,84 C682,126 655,192 628,216 C600,226 575,204 542,214 C490,220 420,212 372,198 Z\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.8\" stroke-dasharray=\"5,3\"/>\n\n  <!-- 四条边方向箭头与力学阶段说明 -->\n  <line x1=\"382\" y1=\"192\" x2=\"416\" y2=\"108\" stroke=\"#12615a\" stroke-width=\"2\" marker-end=\"url(#pdd-arr-g)\"/>\n  <line x1=\"450\" y1=\"90\" x2=\"640\" y2=\"90\" stroke=\"#12615a\" stroke-width=\"2\" marker-end=\"url(#pdd-arr-g)\"/>\n  <line x1=\"666\" y1=\"104\" x2=\"632\" y2=\"188\" stroke=\"#c27a2c\" stroke-width=\"2\" marker-end=\"url(#pdd-arr-a)\"/>\n  <line x1=\"600\" y1=\"206\" x2=\"404\" y2=\"206\" stroke=\"#3a6ea5\" stroke-width=\"2\"/>\n\n  <!-- A / B / C / D 四个顶点圆标 -->\n  <circle cx=\"376\" cy=\"206\" r=\"5\" fill=\"#12615a\"/>\n  <text x=\"366\" y=\"222\" fill=\"#12615a\" font-size=\"10.5\" font-weight=\"700\">A</text>\n  <circle cx=\"424\" cy=\"90\" r=\"5\" fill=\"#2f7d5b\"/>\n  <text x=\"418\" y=\"80\" fill=\"#2f7d5b\" font-size=\"10.5\" font-weight=\"700\">B (SV开)</text>\n  <circle cx=\"672\" cy=\"90\" r=\"5\" fill=\"#c27a2c\"/>\n  <text x=\"668\" y=\"80\" fill=\"#c27a2c\" font-size=\"10.5\" font-weight=\"700\">C (SV关)</text>\n  <circle cx=\"624\" cy=\"206\" r=\"5\" fill=\"#3a6ea5\"/>\n  <text x=\"624\" y=\"222\" fill=\"#3a6ea5\" font-size=\"10.5\" font-weight=\"700\">D (TV开)</text>\n\n  <!-- 四冲程机理解释浮窗 -->\n  <rect x=\"434\" y=\"104\" width=\"186\" height=\"86\" rx=\"5\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"442\" y=\"120\" fill=\"#12615a\" font-size=\"9.5\"><tspan font-weight=\"700\">A→B 加载</tspan>：双阀均关，液柱重移至杆柱</text>\n  <text x=\"442\" y=\"138\" fill=\"#2f7d5b\" font-size=\"9.5\"><tspan font-weight=\"700\">B→C 排液</tspan>：SV开、TV关，光杆提液上行</text>\n  <text x=\"442\" y=\"156\" fill=\"#c27a2c\" font-size=\"9.5\"><tspan font-weight=\"700\">C→D 卸载</tspan>：上死点换向，杆柱弹性收缩卸载</text>\n  <text x=\"442\" y=\"174\" fill=\"#3a6ea5\" font-size=\"9.5\"><tspan font-weight=\"700\">D→A 充液</tspan>：TV开、SV关，柱塞下行进液</text>\n\n  <text x=\"530\" y=\"64\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"9.5\">虚线：地面实测功图（叠加 2000m 杆柱弹性振动谐波）</text>\n\n  <!-- 底部：人工巡检三大痛点数据对比条 (y: 296..342) -->\n  <rect x=\"16\" y=\"296\" width=\"728\" height=\"44\" rx=\"6\" fill=\"#f6e3df\" stroke=\"rgba(180,72,60,0.35)\"/>\n  <text x=\"28\" y=\"315\" fill=\"#b4483c\" font-size=\"10.5\" font-weight=\"700\">传统人工巡检三大瓶颈</text>\n  <text x=\"28\" y=\"331\" fill=\"#424a50\" font-size=\"10\">① <tspan font-weight=\"700\">海量漏看</tspan>：单采油厂 2,500 口井 × 144 张/日 = <tspan font-weight=\"700\" fill=\"#b4483c\">36 万张/日</tspan>，人工抽检率 &lt; 3%</text>\n  <text x=\"382\" y=\"315\" fill=\"#424a50\" font-size=\"10\">② <tspan font-weight=\"700\">地面失真误判</tspan>：千米杆柱振动掩盖井下泵阀真实形态，主观分歧率 <tspan font-weight=\"700\" fill=\"#b4483c\">22%</tspan></text>\n  <text x=\"382\" y=\"331\" fill=\"#424a50\" font-size=\"10\">③ <tspan font-weight=\"700\">检泵滞后</tspan>：抽油杆断脱或凡尔严重漏失平均滞后 <tspan font-weight=\"700\" fill=\"#b4483c\">3–7 天</tspan> 才发现，造成偏磨与空抽</text>\n</svg>\n</div>\n<div class=\"figcap\"><b>图 1</b><span>游梁式抽油机—深井泵四冲程循环机理与理想平行四边形示功图（A→B→C→D）：闭合环面积直接度量单冲程有效排液做功。</span></div>\n<p>一旦井下发生地层供液不足、游离气侵入、凡尔球座磨损漏失或抽油杆疲劳脱扣，四个角点（A/B/C/D）的启闭时机与上下冲程斜率就会发生特征性畸变（见<b>图 2</b>）。但传统人工巡检面临三大痛点：<b>① 海量漏看</b>（全厂日产 36 万张功图，人工仅能抽看不足 3%）；<b>② 杆柱振动掩盖</b>（2000 米细长钢杆如同弹簧，地面实测功图叠加剧烈谐波振荡，人工极易把杆柱惯性波误判为结蜡或漏失）；<b>③ 处置严重滞后</b>（抽油杆断脱或严重漏失往往延误 3–7 天才被发现，既损失百吨原油又造成断杆偏磨穿孔）。</p>\n<div class=\"figure\">\n<svg viewBox=\"0 0 760 320\" width=\"100%\" role=\"img\" aria-label=\"八类典型井下工况的示功图几何形态图谱\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"320\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"380\" y=\"22\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"12\" font-weight=\"700\">八类典型井下工况的示功图闭合几何指纹图谱（虚线框为理想基准，实线为井下泵功图）</text>\n\n  <!-- 第一行 4 格 (y: 34..168) -->\n  <!-- 1. 正常工况 -->\n  <g transform=\"translate(14,34)\">\n    <rect x=\"0\" y=\"0\" width=\"174\" height=\"132\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#2f7d5b\" font-size=\"11\" font-weight=\"700\">01 正常生产工况</text>\n    <text x=\"164\" y=\"18\" text-anchor=\"end\" fill=\"#2f7d5b\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">η=0.92</text>\n    <polygon points=\"22,94 38,34 152,34 136,94\" fill=\"rgba(47,125,91,0.12)\" stroke=\"#2f7d5b\" stroke-width=\"2\"/>\n    <text x=\"87\" y=\"112\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">饱满平行四边形 · 双阀启闭干脆</text>\n    <text x=\"87\" y=\"125\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"9\">维持当前冲程冲次参数</text>\n  </g>\n\n  <!-- 2. 供液不足 -->\n  <g transform=\"translate(200,34)\">\n    <rect x=\"0\" y=\"0\" width=\"174\" height=\"132\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#c27a2c\" font-size=\"11\" font-weight=\"700\">02 供液不足 (刀把形)</text>\n    <text x=\"164\" y=\"18\" text-anchor=\"end\" fill=\"#c27a2c\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">η=0.51</text>\n    <polygon points=\"22,94 38,34 152,34 136,94\" fill=\"none\" stroke=\"#c7cfd6\" stroke-dasharray=\"3,2\"/>\n    <polygon points=\"22,94 38,34 152,34 94,38 82,94\" fill=\"rgba(194,122,44,0.15)\" stroke=\"#c27a2c\" stroke-width=\"2\"/>\n    <ellipse cx=\"122\" cy=\"70\" rx=\"24\" ry=\"18\" fill=\"rgba(180,72,60,0.16)\" stroke=\"#b4483c\" stroke-dasharray=\"2,2\"/>\n    <text x=\"122\" y=\"73\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"8.5\" font-weight=\"600\">右下缺失</text>\n    <text x=\"87\" y=\"112\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">柱塞下行撞击未充满液面才卸载</text>\n    <text x=\"87\" y=\"125\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"9\">对策：调小冲次或间歇抽油</text>\n  </g>\n\n  <!-- 3. 气体影响 / 气锁 -->\n  <g transform=\"translate(386,34)\">\n    <rect x=\"0\" y=\"0\" width=\"174\" height=\"132\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#3a6ea5\" font-size=\"11\" font-weight=\"700\">03 气体影响 / 气锁</text>\n    <text x=\"164\" y=\"18\" text-anchor=\"end\" fill=\"#3a6ea5\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">η=0.46</text>\n    <polygon points=\"22,94 38,34 152,34 136,94\" fill=\"none\" stroke=\"#c7cfd6\" stroke-dasharray=\"3,2\"/>\n    <path d=\"M22,94 C35,50 85,34 152,34 C140,78 90,94 22,94 Z\" fill=\"rgba(58,110,165,0.15)\" stroke=\"#3a6ea5\" stroke-width=\"2\"/>\n    <text x=\"87\" y=\"112\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">游离气压缩膨胀 · 香蕉/椭圆弧</text>\n    <text x=\"87\" y=\"125\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"9\">对策：套管放气 + 加深泵挂</text>\n  </g>\n\n  <!-- 4. 游动阀漏失 -->\n  <g transform=\"translate(572,34)\">\n    <rect x=\"0\" y=\"0\" width=\"174\" height=\"132\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#b4483c\" font-size=\"11\" font-weight=\"700\">04 游动阀 (TV) 漏失</text>\n    <text x=\"164\" y=\"18\" text-anchor=\"end\" fill=\"#b4483c\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">η=0.58</text>\n    <polygon points=\"22,94 38,34 152,34 136,94\" fill=\"none\" stroke=\"#c7cfd6\" stroke-dasharray=\"3,2\"/>\n    <path d=\"M22,94 Q86,12 152,68 L136,94 Z\" fill=\"rgba(180,72,60,0.14)\" stroke=\"#b4483c\" stroke-width=\"2\"/>\n    <text x=\"87\" y=\"112\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">上冲程加载慢 · 顶部拱起抛物线</text>\n    <text x=\"87\" y=\"125\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9\">对策：热洗或检泵换游动阀</text>\n  </g>\n\n  <!-- 第二行 4 格 (y: 176..310) -->\n  <!-- 5. 固定阀漏失 -->\n  <g transform=\"translate(14,176)\">\n    <rect x=\"0\" y=\"0\" width=\"174\" height=\"132\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#6b5aa6\" font-size=\"11\" font-weight=\"700\">05 固定阀 (SV) 漏失</text>\n    <text x=\"164\" y=\"18\" text-anchor=\"end\" fill=\"#6b5aa6\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">η=0.56</text>\n    <polygon points=\"22,94 38,34 152,34 136,94\" fill=\"none\" stroke=\"#c7cfd6\" stroke-dasharray=\"3,2\"/>\n    <path d=\"M22,62 L38,34 L152,34 Q90,112 22,62 Z\" fill=\"rgba(107,90,166,0.14)\" stroke=\"#6b5aa6\" stroke-width=\"2\"/>\n    <text x=\"87\" y=\"112\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">下冲程卸载迟缓 · 底部内凹上拱</text>\n    <text x=\"87\" y=\"125\" text-anchor=\"middle\" fill=\"#6b5aa6\" font-size=\"9\">对策：检泵打捞更换固定阀</text>\n  </g>\n\n  <!-- 6. 抽油杆断脱 -->\n  <g transform=\"translate(200,176)\">\n    <rect x=\"0\" y=\"0\" width=\"174\" height=\"132\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#b4483c\" font-size=\"11\" font-weight=\"700\">06 抽油杆断脱</text>\n    <text x=\"164\" y=\"18\" text-anchor=\"end\" fill=\"#b4483c\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">η=0.06</text>\n    <polygon points=\"22,94 38,34 152,34 136,94\" fill=\"none\" stroke=\"#c7cfd6\" stroke-dasharray=\"3,2\"/>\n    <ellipse cx=\"87\" cy=\"78\" rx=\"64\" ry=\"5\" fill=\"rgba(180,72,60,0.22)\" stroke=\"#b4483c\" stroke-width=\"2\"/>\n    <text x=\"87\" y=\"112\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">扁平水平窄条 · 仅剩断口以上杆重</text>\n    <text x=\"87\" y=\"125\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9\">对策：P0 紧急停机 + 修井打捞</text>\n  </g>\n\n  <!-- 7. 连抽带喷 -->\n  <g transform=\"translate(386,176)\">\n    <rect x=\"0\" y=\"0\" width=\"174\" height=\"132\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#12615a\" font-size=\"11\" font-weight=\"700\">07 连抽带喷</text>\n    <text x=\"164\" y=\"18\" text-anchor=\"end\" fill=\"#12615a\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">η=0.24</text>\n    <polygon points=\"22,94 38,34 152,34 136,94\" fill=\"none\" stroke=\"#c7cfd6\" stroke-dasharray=\"3,2\"/>\n    <polygon points=\"24,88 34,72 150,52 138,68\" fill=\"rgba(18,97,90,0.14)\" stroke=\"#12615a\" stroke-width=\"2\"/>\n    <text x=\"87\" y=\"112\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">地层自喷能量顶开双阀 · 倾斜窄带</text>\n    <text x=\"87\" y=\"125\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"9\">对策：监控油压防井口刺漏</text>\n  </g>\n\n  <!-- 8. 结蜡 / 活塞卡阻 -->\n  <g transform=\"translate(572,176)\">\n    <rect x=\"0\" y=\"0\" width=\"174\" height=\"132\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#c27a2c\" font-size=\"11\" font-weight=\"700\">08 结蜡 / 活塞砂卡</text>\n    <text x=\"164\" y=\"18\" text-anchor=\"end\" fill=\"#c27a2c\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">η=1.08</text>\n    <polygon points=\"22,94 38,34 152,34 136,94\" fill=\"none\" stroke=\"#c7cfd6\" stroke-dasharray=\"3,2\"/>\n    <polygon points=\"22,94 36,34 52,24 68,38 86,22 104,37 122,25 152,34 138,94 116,102 96,88 74,104 52,90\" fill=\"rgba(194,122,44,0.14)\" stroke=\"#c27a2c\" stroke-width=\"1.8\"/>\n    <text x=\"87\" y=\"112\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">上下冲程剧烈锯齿尖峰 · 附加阻力</text>\n    <text x=\"87\" y=\"125\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"9\">对策：安排热洗清蜡或加降粘剂</text>\n  </g>\n</svg>\n</div>\n<div class=\"figcap\"><b>图 2</b><span>八类典型井下工况的示功图几何形态图谱：不同故障在四个角点（A/B/C/D）与上下边产生具有明确力学机理的几何畸变。</span></div>\n"},{"no":2,"en":"","title":"AI 能做什么","html":"<p>高可靠性的智能诊断绝不能把地面失真功图直接丢进黑盒分类器，而是采用<b>「物理机理反演 + 双分支多模态深度识别」</b>架构（见<b>图 3</b>）：</p><p><b>第一步（物理去失真）：吉布斯（Gibbs）一维阻尼波动方程反演。</b>将地面光杆实测载荷与位移作为边界条件，沿多级抽油杆柱向下求解一维阻尼波动方程，精确剥离杆柱自身重力、惯性驻波与井筒粘滞摩擦阻尼，还原出反映井下柱塞真实受力的<b>井下泵功图（Downhole Pump Card）</b>。</p><p><b>第二步（双分支协同识别）：</b>分支一将归一化闭合泵功图渲染为 64×64 双通道栅格环，用轻量 <b>ResNet-18 + Grad-CAM</b> 捕捉角点缺损与刮蜡锯齿纹理；分支二提取闭合轮廓的 <b>16 阶复数傅里叶形状描述子（FD₁–FD₁₆）</b>及 5 项油藏工程算子（泵功图饱满度 <code>η</code>、右下角缺失率 <code>ΔD</code>、上下加载斜率比、载荷极差比、高阶谐波能量）。两者融合后经温度缩放校准，同步输出<b>工况概率、折算有效排液量与检泵优先级工单</b>。</p>\n<div class=\"figure\">\n<svg viewBox=\"0 0 760 285\" width=\"100%\" role=\"img\" aria-label=\"吉布斯波动方程反演与傅里叶描述子/CNN双分支诊断架构\">\n  <defs>\n    <marker id=\"pdd-f3-arr\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\">\n      <path d=\"M0,1 L9,5 L0,9 Z\" fill=\"#12615a\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"285\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"380\" y=\"22\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"12\" font-weight=\"700\">物理机理反演（Gibbs 一维波动方程）+ 双分支深度诊断（2D-CNN + 傅里叶形状描述子）协同架构</text>\n\n  <!-- 模块 1：地面光杆传感器输入 (x: 14..154) -->\n  <rect x=\"14\" y=\"38\" width=\"140\" height=\"202\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n  <rect x=\"14\" y=\"38\" width=\"140\" height=\"24\" rx=\"6\" fill=\"#f0ede5\"/>\n  <text x=\"84\" y=\"54\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"10.5\" font-weight=\"700\">1. 地面光杆实测功图</text>\n  <polygon points=\"30,142 46,86 138,86 122,142\" fill=\"none\" stroke=\"#d9d4c8\" stroke-dasharray=\"2,2\"/>\n  <path d=\"M28,138 C40,92 52,74 68,84 C84,92 104,76 138,84 C140,118 112,118 98,88 C86,92 78,142 28,138 Z\" fill=\"rgba(18,97,90,0.12)\" stroke=\"#12615a\" stroke-width=\"1.8\"/>\n  <text x=\"84\" y=\"166\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">载荷 P(0,t) · 位移 S(0,t)</text>\n  <text x=\"84\" y=\"182\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9\">含 2000m 杆柱惯性谐波</text>\n  <text x=\"84\" y=\"196\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9\">与井口/管杆摩擦失真</text>\n  <text x=\"84\" y=\"222\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"9\" font-family=\"ui-monospace,Consolas,monospace\">重采样 N=128 点</text>\n\n  <line x1=\"154\" y1=\"138\" x2=\"176\" y2=\"138\" stroke=\"#12615a\" stroke-width=\"2\" marker-end=\"url(#pdd-f3-arr)\"/>\n\n  <!-- 模块 2：Gibbs 一维阻尼波动方程反演 (x: 178..356) -->\n  <rect x=\"178\" y=\"38\" width=\"178\" height=\"202\" rx=\"6\" fill=\"#ffffff\" stroke=\"#12615a\" stroke-width=\"1.5\"/>\n  <rect x=\"178\" y=\"38\" width=\"178\" height=\"24\" rx=\"6\" fill=\"#e3efec\"/>\n  <text x=\"267\" y=\"54\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"10.5\" font-weight=\"700\">2. Gibbs 波动方程泵功图反演</text>\n  <rect x=\"188\" y=\"70\" width=\"158\" height=\"34\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"267\" y=\"85\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">∂²u/∂t² = a²∂²u/∂x² - c·∂u/∂t</text>\n  <text x=\"267\" y=\"98\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"8.5\">剥离杆柱弹性驻波与粘滞阻尼 c</text>\n  <!-- 还原后的井下泵功图 -->\n  <polygon points=\"204,174 218,120 328,120 314,174\" fill=\"none\" stroke=\"#d9d4c8\" stroke-dasharray=\"2,2\"/>\n  <polygon points=\"204,174 218,120 328,120 278,124 268,174\" fill=\"rgba(194,122,44,0.16)\" stroke=\"#c27a2c\" stroke-width=\"2\"/>\n  <text x=\"267\" y=\"196\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"9.5\" font-weight=\"700\">井下真实泵功图 P(L,t)</text>\n  <text x=\"267\" y=\"212\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9\">暴露真实「刀把」缺角与阀漏失</text>\n  <text x=\"267\" y=\"226\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"8.5\">支持多级杆柱 (D₁/D₂/D₃) 递推</text>\n\n  <!-- 分叉箭头至双分支 -->\n  <path d=\"M356,112 L382,86\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.8\" marker-end=\"url(#pdd-f3-arr)\"/>\n  <path d=\"M356,164 L382,190\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.8\" marker-end=\"url(#pdd-f3-arr)\"/>\n\n  <!-- 模块 3A：上分支 2D 栅格 CNN + Grad-CAM (x: 384..576, y: 38..132) -->\n  <rect x=\"384\" y=\"38\" width=\"192\" height=\"94\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n  <text x=\"394\" y=\"55\" fill=\"#3a6ea5\" font-size=\"10.5\" font-weight=\"700\">3A. 视觉分支：轻量 ResNet + CAM</text>\n  <rect x=\"394\" y=\"64\" width=\"46\" height=\"46\" rx=\"4\" fill=\"#edf3f7\" stroke=\"#3a6ea5\"/>\n  <polygon points=\"400,102 406,72 434,72 418,75 414,102\" fill=\"#3a6ea5\" fill-opacity=\"0.35\" stroke=\"#3a6ea5\" stroke-width=\"1.2\"/>\n  <circle cx=\"424\" cy=\"92\" r=\"8\" fill=\"rgba(180,72,60,0.45)\"/>\n  <text x=\"448\" y=\"78\" fill=\"#424a50\" font-size=\"9.5\">64×64 双通道栅格环图</text>\n  <text x=\"448\" y=\"94\" fill=\"#424a50\" font-size=\"9.5\">卷积核捕捉锯齿与局部曲率</text>\n  <text x=\"448\" y=\"110\" fill=\"#b4483c\" font-size=\"9\" font-weight=\"600\">Grad-CAM 定位畸变角点</text>\n\n  <!-- 模块 3B：下分支 傅里叶描述子 + 物理算子 (x: 384..576, y: 146..240) -->\n  <rect x=\"384\" y=\"146\" width=\"192\" height=\"94\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n  <text x=\"394\" y=\"163\" fill=\"#c27a2c\" font-size=\"10.5\" font-weight=\"700\">3B. 频域与机理算子分支</text>\n  <text x=\"394\" y=\"182\" fill=\"#424a50\" font-size=\"9.5\">• 复数轮廓傅里叶描述子 FD₁–FD₁₆</text>\n  <text x=\"394\" y=\"198\" fill=\"#424a50\" font-size=\"9.5\">• 泵功图饱满度 η = A_pump / A_ideal</text>\n  <text x=\"394\" y=\"214\" fill=\"#424a50\" font-size=\"9.5\">• 右下缺失率 ΔD + 上下加载斜率比</text>\n  <text x=\"394\" y=\"229\" fill=\"#2f7d5b\" font-size=\"9\" font-weight=\"600\">天然具备平移/缩放/起抽点不变性</text>\n\n  <!-- 汇合箭头至模块 4 -->\n  <path d=\"M576,86 L600,122\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.8\" marker-end=\"url(#pdd-f3-arr)\"/>\n  <path d=\"M576,190 L600,154\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.8\" marker-end=\"url(#pdd-f3-arr)\"/>\n\n  <!-- 模块 4：融合分类、产液折算与检泵排程 (x: 602..746, y: 38..240) -->\n  <rect x=\"602\" y=\"38\" width=\"144\" height=\"202\" rx=\"6\" fill=\"#ffffff\" stroke=\"#12615a\" stroke-width=\"1.5\"/>\n  <rect x=\"602\" y=\"38\" width=\"144\" height=\"24\" rx=\"6\" fill=\"#12615a\"/>\n  <text x=\"674\" y=\"54\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"10.5\" font-weight=\"700\">4. 决策输出与排程</text>\n  <text x=\"612\" y=\"80\" fill=\"#15191c\" font-size=\"9.5\" font-weight=\"700\">① 工况概率 (校准后)</text>\n  <rect x=\"612\" y=\"86\" width=\"120\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/>\n  <rect x=\"612\" y=\"86\" width=\"108\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/>\n  <text x=\"612\" y=\"108\" fill=\"#c27a2c\" font-size=\"9\" font-family=\"ui-monospace,Consolas,monospace\">供液不足: 94.6%</text>\n\n  <text x=\"612\" y=\"132\" fill=\"#15191c\" font-size=\"9.5\" font-weight=\"700\">② 折算有效排液量 Q</text>\n  <text x=\"612\" y=\"148\" fill=\"#12615a\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\">Q = 14.2 m³/d (53%)</text>\n\n  <text x=\"612\" y=\"174\" fill=\"#15191c\" font-size=\"9.5\" font-weight=\"700\">③ 检泵与调参工单</text>\n  <rect x=\"612\" y=\"182\" width=\"122\" height=\"44\" rx=\"4\" fill=\"#f7ecdd\" stroke=\"#c27a2c\"/>\n  <text x=\"673\" y=\"198\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"9.5\" font-weight=\"700\">P2 参数优化工单</text>\n  <text x=\"673\" y=\"214\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"8.5\">下调冲次避免液击伤杆</text>\n\n  <!-- 底部总结条 -->\n  <text x=\"380\" y=\"268\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"10.5\"><tspan font-weight=\"700\" fill=\"#15191c\">为什么必须「先物理反演、再双分支识别」？</tspan>直接用地面功图训练 CNN 极易把深井杆柱振动误判为结蜡或漏失；反演井下泵功图后分类 F1 提升 <tspan font-weight=\"700\" fill=\"#12615a\">9.4%</tspan>。</text>\n</svg>\n</div>\n<div class=\"figcap\"><b>图 3</b><span>物理反演与深度学习融合架构：先用吉布斯波动方程消去千米抽油杆弹性失真，再联合 2D-CNN 与傅里叶形状描述子输出可解释诊断。</span></div>\n<div class=\"callout\"><span class=\"ci\">核心价值</span><span>AI 不仅替掉了「逐井肉眼看图」，更通过波动方程反演 + 饱满度算子把<b>「只需调小冲次的地层供液不足」</b>与<b>「必须派修井队起泵的凡尔漏失」</b>严格区分开，单厂每年可避免数百井次无效检泵作业。</span></div>"},{"no":3,"en":"","title":"需要准备什么","html":"<p>落地一套采油厂级示功图诊断系统，需要准备<b>井口传感器时序、井身管杆台账、检泵拆解金标准图库</b>三类核心资产（可点击下方清单逐项核对）：</p>\n<div class=\"checklist\">\n  <div class=\"cl-head\">\n    <span>数据准备清单 · 3 项</span>\n    <span class=\"cl-prog\"><span id=\"cl-txt\">0 / 3</span><span class=\"cl-bar\"><i id=\"cl-fill\"></i></span></span>\n  </div>\n  <div class=\"cl-item\" data-cl=\"0\">\n    <span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span>\n    <span>\n      <span class=\"cl-t\">光杆载荷—位移闭合序列与冲程冲次</span>\n      <span class=\"cl-s\">单冲程 100–250 个采样点 (P, S)，含冲程 S₀ (m)、冲次 n (min⁻¹) 与采集时间戳</span>\n    </span>\n    <span class=\"cl-n\">剔除传感器零漂与未闭合残缺环</span>\n  </div>\n  <div class=\"cl-item\" data-cl=\"1\">\n    <span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span>\n    <span>\n      <span class=\"cl-t\">井下泵深、泵径、杆柱级配与流体物性参数</span>\n      <span class=\"cl-s\">泵挂深度 L、泵径 Dp、多级抽油杆直径/长度比、原油密度与含水率</span>\n    </span>\n    <span class=\"cl-n\">用于 Gibbs 波动方程反演井下泵功图</span>\n  </div>\n  <div class=\"cl-item\" data-cl=\"2\">\n    <span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span>\n    <span>\n      <span class=\"cl-t\">经检泵作业拆解与液面测试验证的多工况标定图库</span>\n      <span class=\"cl-s\">覆盖 8 类以上典型工况 ≥ 5,000 张历史功图，其中漏失与断脱井需绑定修井起泵记录</span>\n    </span>\n    <span class=\"cl-n\">三级专家交叉审核 + 作业拆解金标准</span>\n  </div>\n</div>\n<p>在样本构建上，油田现场数据呈现极端的<b>长尾分布</b>（正常生产与轻度供液不足占近 90%，而抽油杆断脱、固定阀严重漏失及复合工况合计不足 5%）。必须通过<b>波动方程正演合成罕见故障样本</b>，并建立「井口 RTU 采集 → AI 告警 → 修井起泵实物拆解核验 → 难例样本回流」的闭环迭代机制（见<b>图 4</b>）。</p>\n<div class=\"figure\">\n<svg viewBox=\"0 0 760 250\" width=\"100%\" role=\"img\" aria-label=\"采油厂全井网样本长尾分布与检泵作业拆解验证闭环\">\n  <defs>\n    <marker id=\"pdd-f4-arr\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\">\n      <path d=\"M0,1 L9,5 L0,9 Z\" fill=\"#12615a\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"250\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <line x1=\"416\" y1=\"14\" x2=\"416\" y2=\"236\" stroke=\"#e7e3da\" stroke-dasharray=\"4,3\"/>\n\n  <!-- 左半：采油厂 12.6 万张标定功图样本长尾分布 (x: 16..404) -->\n  <text x=\"210\" y=\"24\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">① 采油厂全井网样本长尾分布（N = 126,000 张标定功图）</text>\n\n  <g font-size=\"10.5\" fill=\"#424a50\">\n    <text x=\"20\" y=\"54\">正常生产</text>\n    <rect x=\"108\" y=\"42\" width=\"236\" height=\"15\" rx=\"3\" fill=\"#2f7d5b\"/>\n    <text x=\"350\" y=\"54\" fill=\"#2f7d5b\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">78.2%</text>\n\n    <text x=\"20\" y=\"84\">供液不足</text>\n    <rect x=\"108\" y=\"72\" width=\"68\" height=\"15\" rx=\"3\" fill=\"#c27a2c\"/>\n    <text x=\"182\" y=\"84\" fill=\"#c27a2c\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">11.4%</text>\n\n    <text x=\"20\" y=\"114\">气体影响/气锁</text>\n    <rect x=\"108\" y=\"102\" width=\"38\" height=\"15\" rx=\"3\" fill=\"#3a6ea5\"/>\n    <text x=\"152\" y=\"114\" fill=\"#3a6ea5\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">4.8%</text>\n\n    <text x=\"20\" y=\"144\">游动/固定阀漏</text>\n    <rect x=\"108\" y=\"132\" width=\"28\" height=\"15\" rx=\"3\" fill=\"#6b5aa6\"/>\n    <text x=\"142\" y=\"144\" fill=\"#6b5aa6\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">3.5%</text>\n\n    <text x=\"20\" y=\"174\">杆断脱/连抽带喷</text>\n    <rect x=\"108\" y=\"162\" width=\"14\" height=\"15\" rx=\"3\" fill=\"#b4483c\"/>\n    <text x=\"128\" y=\"174\" fill=\"#b4483c\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">1.2%</text>\n\n    <text x=\"20\" y=\"204\">疑难复合工况</text>\n    <rect x=\"108\" y=\"192\" width=\"11\" height=\"15\" rx=\"3\" fill=\"#b4483c\"/>\n    <text x=\"125\" y=\"204\" fill=\"#b4483c\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">0.9%</text>\n  </g>\n\n  <rect x=\"196\" y=\"128\" width=\"204\" height=\"82\" rx=\"5\" fill=\"#f6e3df\" stroke=\"rgba(180,72,60,0.35)\"/>\n  <text x=\"206\" y=\"146\" fill=\"#b4483c\" font-size=\"10\" font-weight=\"700\">长尾失衡对策（Focal Loss + 物理增广）</text>\n  <text x=\"206\" y=\"164\" fill=\"#424a50\" font-size=\"9.5\">• 正常井占近 8 成，直接训练会导致断杆漏报</text>\n  <text x=\"206\" y=\"180\" fill=\"#424a50\" font-size=\"9.5\">• 用波动方程正演合成罕见断脱/漏失样本</text>\n  <text x=\"206\" y=\"196\" fill=\"#424a50\" font-size=\"9.5\">• 关键故障类别赋予 8× 代价敏感权重</text>\n  <text x=\"20\" y=\"232\" fill=\"#737c83\" font-size=\"9.5\">注：仅靠RTU无标签功图不够，凡尔漏失与断脱必须以「检泵拆解记录」为金标准。</text>\n\n  <!-- 右半：检泵作业拆解对标闭环 (x: 428..746) -->\n  <text x=\"588\" y=\"24\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">② 「井口RTU采集—AI诊断—检泵拆解验证」金标准闭环</text>\n\n  <rect x=\"440\" y=\"44\" width=\"128\" height=\"62\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n  <text x=\"504\" y=\"64\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"10.5\" font-weight=\"700\">1. RTU 边缘采集</text>\n  <text x=\"504\" y=\"80\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9\">每 10 分钟上传闭合序列</text>\n  <text x=\"504\" y=\"94\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"8.5\">同步动液面与电流曲线</text>\n\n  <line x1=\"568\" y1=\"75\" x2=\"602\" y2=\"75\" stroke=\"#12615a\" stroke-width=\"1.8\" marker-end=\"url(#pdd-f4-arr)\"/>\n\n  <rect x=\"604\" y=\"44\" width=\"134\" height=\"62\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n  <text x=\"671\" y=\"64\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"10.5\" font-weight=\"700\">2. AI 泵功图分级告警</text>\n  <text x=\"671\" y=\"80\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9\">连续 3 周期异常触发工单</text>\n  <text x=\"671\" y=\"94\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"8.5\">区分「调参井」与「检泵井」</text>\n\n  <line x1=\"671\" y1=\"106\" x2=\"671\" y2=\"138\" stroke=\"#12615a\" stroke-width=\"1.8\" marker-end=\"url(#pdd-f4-arr)\"/>\n\n  <rect x=\"604\" y=\"140\" width=\"134\" height=\"66\" rx=\"6\" fill=\"#f7ecdd\" stroke=\"#c27a2c\"/>\n  <text x=\"671\" y=\"160\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"10.5\" font-weight=\"700\">3. 现场修井起泵拆解</text>\n  <text x=\"671\" y=\"176\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9\">实物拍照核验：阀球刺穿、</text>\n  <text x=\"671\" y=\"190\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9\">固定阀砂卡、杆断口位置</text>\n\n  <line x1=\"604\" y1=\"173\" x2=\"570\" y2=\"173\" stroke=\"#12615a\" stroke-width=\"1.8\" marker-end=\"url(#pdd-f4-arr)\"/>\n\n  <rect x=\"440\" y=\"140\" width=\"128\" height=\"66\" rx=\"6\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"504\" y=\"160\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"10.5\" font-weight=\"700\">4. 金标准样本回流</text>\n  <text x=\"504\" y=\"176\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9\">修正高歧义样本标签</text>\n  <text x=\"504\" y=\"190\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"8.5\" font-weight=\"600\">季度增量微调模型权重</text>\n\n  <line x1=\"504\" y1=\"140\" x2=\"504\" y2=\"108\" stroke=\"#12615a\" stroke-width=\"1.8\" marker-end=\"url(#pdd-f4-arr)\"/>\n  <text x=\"588\" y=\"232\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">闭环收益：无效应急检泵减少 <tspan font-weight=\"700\" fill=\"#12615a\">34%</tspan>，疑难漏失识别率由 76% 升至 <tspan font-weight=\"700\" fill=\"#12615a\">93.5%</tspan></text>\n</svg>\n</div>\n<div class=\"figcap\"><b>图 4</b><span>采油厂样本严重长尾分布与「RTU采集—AI告警—现场起泵拆解验证—难例回流」金标准闭环机制。</span></div>\n"},{"no":4,"en":"","title":"难度与参考方向","html":"<p>在老油田高含水开发后期与丛式定向井区块，模型面临三大深水区挑战（见<b>图 5</b>）：</p><p><b>① 复合工况非线性耦合：</b>如「供液不足 + 气体影响」同时发生时，右下角刀把形急剧卸载台阶会被游离气膨胀圆弧抹平，单标签分类器容易摇摆；工程上需改用<b>多标签解耦头（Multi-label Sigmoid）</b>同步回归充满度与气侵指数。<br/><b>② 大斜度井/狗腿度井偏磨失真：</b>定向井段抽油杆紧贴油管内壁产生剧烈库仑干摩擦，导致地面功图异常肥大；需引入三维井眼轨迹（井斜角、方位角）修正波动方程阻尼项。<br/><b>③ 电功图多模态互证：</b>当井口载荷传感器发生零点漂移时，可联合变频控制柜采集的<b>电机有功功率时间序列（电功图）</b>进行跨模态交叉验证。</p>\n<div class=\"figure\">\n<svg viewBox=\"0 0 760 255\" width=\"100%\" role=\"img\" aria-label=\"复合工况特征耦合与工程落地难度剖析\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"255\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"380\" y=\"22\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"12\" font-weight=\"700\">老油田高含水后期两大核心难点：多故障形态非线性耦合 &amp; 定向斜井库仑摩擦失真</text>\n\n  <!-- 左卡片：复合工况 1（供液不足 + 气体影响） -->\n  <g transform=\"translate(16,36)\">\n    <rect x=\"0\" y=\"0\" width=\"232\" height=\"198\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"116\" y=\"20\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"11\" font-weight=\"700\">难点 A：供液不足 + 气体影响耦合</text>\n    <polygon points=\"34,118 52,48 196,48 178,118\" fill=\"none\" stroke=\"#d9d4c8\" stroke-dasharray=\"3,2\"/>\n    <!-- 刀把形 (虚线琥珀) vs 耦合圆化刀把 (实线红) -->\n    <polygon points=\"34,118 52,48 196,48 126,52 114,118\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.4\" stroke-dasharray=\"3,2\"/>\n    <path d=\"M34,118 C48,68 78,48 196,48 C184,82 142,88 112,118 Z\" fill=\"rgba(180,72,60,0.15)\" stroke=\"#b4483c\" stroke-width=\"2\"/>\n    <text x=\"116\" y=\"140\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"9.5\" font-weight=\"600\">台阶急剧卸载被气侵圆弧抹平</text>\n    <text x=\"14\" y=\"158\" fill=\"#424a50\" font-size=\"9\">• 单标签 Softmax 易在两类间摇摆</text>\n    <text x=\"14\" y=\"174\" fill=\"#12615a\" font-size=\"9\" font-weight=\"600\">• 方案：改用 Sigmoid 多标签解耦输出</text>\n    <text x=\"14\" y=\"190\" fill=\"#737c83\" font-size=\"8.5\">同时输出 [充满度 η, 气侵指数 γ]</text>\n  </g>\n\n  <!-- 中卡片：复合工况 2（结蜡卡阻 + 游动阀漏失） -->\n  <g transform=\"translate(264,36)\">\n    <rect x=\"0\" y=\"0\" width=\"232\" height=\"198\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"116\" y=\"20\" text-anchor=\"middle\" fill=\"#6b5aa6\" font-size=\"11\" font-weight=\"700\">难点 B：结蜡卡阻 + 游动阀漏失耦合</text>\n    <polygon points=\"34,118 52,48 196,48 178,118\" fill=\"none\" stroke=\"#d9d4c8\" stroke-dasharray=\"3,2\"/>\n    <path d=\"M34,118 L48,74 L62,56 L78,66 L96,42 L116,58 L138,46 L162,68 L194,82 L176,118 L142,124 L112,112 L78,124 Z\" fill=\"rgba(107,90,166,0.14)\" stroke=\"#6b5aa6\" stroke-width=\"2\"/>\n    <text x=\"116\" y=\"140\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"9.5\" font-weight=\"600\">高频刮蜡锯齿掩盖顶部抛物线拱曲</text>\n    <text x=\"14\" y=\"158\" fill=\"#424a50\" font-size=\"9\">• 仅看高阶傅里叶能量会漏诊凡尔漏失</text>\n    <text x=\"14\" y=\"174\" fill=\"#12615a\" font-size=\"9\" font-weight=\"600\">• 方案：低阶 FD₁–FD₃ 抓宏观包络 +</text>\n    <text x=\"14\" y=\"190\" fill=\"#737c83\" font-size=\"8.5\">高阶 FD₆–FD₁₆ 独立量化刮蜡冲击</text>\n  </g>\n\n  <!-- 右卡片：定向井/大斜度井三维库仑摩擦挑战与路线图 -->\n  <g transform=\"translate(512,36)\">\n    <rect x=\"0\" y=\"0\" width=\"232\" height=\"198\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <text x=\"116\" y=\"20\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"11\" font-weight=\"700\">难点 C：大斜度井偏磨与模型演进</text>\n\n    <text x=\"14\" y=\"46\" fill=\"#424a50\" font-size=\"9.5\" font-weight=\"600\">工程难度评估</text>\n    <text x=\"14\" y=\"64\" fill=\"#424a50\" font-size=\"9\">直井波动方程反演</text>\n    <rect x=\"118\" y=\"55\" width=\"96\" height=\"9\" rx=\"3\" fill=\"#f0ede5\"/>\n    <rect x=\"118\" y=\"55\" width=\"38\" height=\"9\" rx=\"3\" fill=\"#2f7d5b\"/>\n\n    <text x=\"14\" y=\"84\" fill=\"#424a50\" font-size=\"9\">大斜度井库仑摩擦</text>\n    <rect x=\"118\" y=\"75\" width=\"96\" height=\"9\" rx=\"3\" fill=\"#f0ede5\"/>\n    <rect x=\"118\" y=\"75\" width=\"76\" height=\"9\" rx=\"3\" fill=\"#c27a2c\"/>\n\n    <text x=\"14\" y=\"104\" fill=\"#424a50\" font-size=\"9\">复合故障零样本泛化</text>\n    <rect x=\"118\" y=\"95\" width=\"96\" height=\"9\" rx=\"3\" fill=\"#f0ede5\"/>\n    <rect x=\"118\" y=\"95\" width=\"84\" height=\"9\" rx=\"3\" fill=\"#b4483c\"/>\n\n    <line x1=\"14\" y1=\"118\" x2=\"218\" y2=\"118\" stroke=\"#ece8df\"/>\n    <text x=\"14\" y=\"136\" fill=\"#12615a\" font-size=\"9.5\" font-weight=\"700\">三阶段进阶路线：</text>\n    <text x=\"14\" y=\"154\" fill=\"#424a50\" font-size=\"9\">① 引入井斜轨迹方位角修正库仑摩擦项</text>\n    <text x=\"14\" y=\"170\" fill=\"#424a50\" font-size=\"9\">② 融合电参（电机有功功率曲线）多模态互证</text>\n    <text x=\"14\" y=\"186\" fill=\"#424a50\" font-size=\"9\">③ 基于物理信息神经网络 (PINN) 反演阻尼</text>\n  </g>\n</svg>\n</div>\n<div class=\"figcap\"><b>图 5</b><span>复合工况特征耦合剖析与大斜度井三维库仑摩擦修正、电参多模态融合进阶路线。</span></div>\n\n<div class=\"refs\">\n  <a class=\"ref\" href=\"#/method/cv\">卷积神经网络与形状描述子<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">吉布斯波动方程时序反演<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/scene/pr1\">采油工程 · 抽油机井工况诊断<span class=\"ar\">↗</span></a>\n</div>\n"}]},"workflow":{"label":"案例流程","title":"从井口光杆信号到全厂检泵排程的五步落地流水线","lead":["整套流水线部署在采油厂边缘网关与生产指挥中心：每口井每 10 分钟上传一组光杆载荷—位移序列，5 毫秒内完成井下泵功图反演与双分支诊断，并按少产液量与设备风险自动生成日度检泵排程表。"],"stats":[["覆盖抽油机井","2,580 口"],["单井反演+推理耗时","4.6 ms"],["检泵拆解符合率","93.8%"]],"steps":[{"name":"载荷—位移闭合归一化与重采样","role":"数据","do":"读取 RTU 采集的单冲程光杆位移 S(t) 与载荷 P(t) 序列，定位上下死点极值，校验首尾闭合残差（< 2%），按等弧长插值重采样为 N=128 个标准闭合轮廓点，并归一化至 [0, 1]²。","effect":"消除不同机型冲程（1.8–4.5m）、冲次（2–8 min⁻¹）与采样率差异，输出标准闭合多边形。","trap":"停机瞬态或皮带打滑会导致功图首尾严重不闭合，必须在预处理阶段直接拦截并打上「采集异常」标签，禁止送入反演方程。"},{"name":"波动方程反演井下泵功图","role":"算法","do":"结合该井泵挂深度 L、多级杆柱级配（如 25mm+22mm+19mm）与阻尼系数 c，采用吉布斯（Gibbs）傅里叶级数法求解一维阻尼波动方程（谐波阶数 N=16），剥离杆柱弹性振动与粘滞摩擦。","effect":"还原井下柱塞处的真实载荷—位移泵功图，使被杆柱谐波掩盖的「右下刀把缺角」与「凡尔漏失抛物线」清晰显现。","trap":"大斜度井或高粘稠油井若沿用固定经验阻尼系数 c，会导致反演泵功图出现“过冲交叉环”，需按下冲程水平段平坦度自适应寻优阻尼系数。"},{"name":"几何饱满度与傅里叶形状特征提取","role":"算法","do":"在井下泵功图上通过鞋带公式计算闭合面积与饱满度系数 η，统计四角区域缺失率（ΔA/ΔB/ΔC/ΔD）与上下加载斜率比；同时对轮廓质心距离序列做离散傅里叶变换提取 FD₁–FD₁₆。","effect":"生成 24 维具有严格油藏物理意义的形状特征向量，对起抽点相位偏移与微小尺度变化完全不变。","trap":"傅里叶描述子必须用直流分量 FD₀ 归一化幅值并丢弃相位角，否则上下死点微小的采样起点抖动会引起特征剧烈跳变。"},{"name":"双分支深度分类与置信度校准","role":"模型","do":"将 64×64 栅格泵功图送入轻量 ResNet 分支提取局部纹理，与 24 维傅里叶及几何算子分支拼接，经温度缩放（T=1.15）Softmax 输出六类工况概率，并生成 Grad-CAM 畸变角点高亮图。","effect":"测试集六类工况 Macro-F1 达 95.8%，同时在功图上直观标出触发该诊断的物理畸变区供采油工程师秒级复核。","trap":"长尾分布下模型容易对罕见的「抽油杆断脱」欠拟合，训练时必须采用 Focal Loss 并对断脱与严重漏失施加代价敏感加权。"},{"name":"全区块异常井分级告警与检泵排程","role":"应用","do":"引入多周期滑动窗口（连续 3 个采集周期确认异常才触发工单），结合泵功图有效冲程折算日少产液量 ΔQ，将异常井划分为 P0（断杆停机）、P1（计划检泵）、P2（调参/放气）三级排程。","effect":"全厂 2,580 口井每日自动筛选出需优先处置的 Top-15 异常井，无效检泵率下降 34%，断杆发现时间缩短至 15 分钟内。","trap":"间歇出砂或瞬时气团经过泵筒会产生单冲程假异常（一过性气锁），严禁单张功图直接触发检泵工单。"}],"metrics":{"title":"流程分镜与验收指标","html":"\n<p>以下流程分镜图展示单井光杆传感器原始时间序列如何经过 <b>5 个标准步骤</b>转化为井下泵功图、物理几何指纹与全区块检泵排程工单：</p>\n<div class=\"figure\">\n<svg viewBox=\"0 0 760 245\" width=\"100%\" role=\"img\" aria-label=\"抽油机井示功图诊断五步流程分镜图\">\n  <defs>\n    <marker id=\"pdd-wf-arr\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\">\n      <path d=\"M0,1 L9,5 L0,9 Z\" fill=\"#12615a\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"245\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n\n  <!-- Panel 01 -->\n  <g transform=\"translate(10,14)\">\n    <rect x=\"0\" y=\"0\" width=\"136\" height=\"216\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"136\" height=\"24\" rx=\"6\" fill=\"#e3efec\"/>\n    <text x=\"10\" y=\"16\" fill=\"#12615a\" font-size=\"10\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">01</text>\n    <text x=\"28\" y=\"16\" fill=\"#15191c\" font-size=\"10\" font-weight=\"700\">闭合归一化重采样</text>\n    <!-- 原始带噪未闭合 vs 归一化环 -->\n    <path d=\"M18,92 C28,54 44,44 62,50 C82,56 104,44 118,52 C122,78 96,82 82,58 C70,64 62,96 22,96\" fill=\"none\" stroke=\"#a3aab0\" stroke-width=\"1.2\"/>\n    <polygon points=\"22,152 34,114 114,114 78,118 70,152\" fill=\"rgba(18,97,90,0.12)\" stroke=\"#12615a\" stroke-width=\"1.8\"/>\n    <circle cx=\"22\" cy=\"152\" r=\"2.5\" fill=\"#12615a\"/>\n    <circle cx=\"114\" cy=\"114\" r=\"2.5\" fill=\"#3a6ea5\"/>\n    <text x=\"68\" y=\"176\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9\" font-weight=\"600\">对齐上下死点 S∈[0,1]</text>\n    <text x=\"68\" y=\"192\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"8.5\">等弧长 N=128 点重采样</text>\n    <text x=\"68\" y=\"206\" text-anchor=\"middle\" fill=\"#2f7d5b\" font-size=\"8.5\">闭合残差 &lt; 0.5%</text>\n  </g>\n  <line x1=\"147\" y1=\"122\" x2=\"157\" y2=\"122\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#pdd-wf-arr)\"/>\n\n  <!-- Panel 02 -->\n  <g transform=\"translate(159,14)\">\n    <rect x=\"0\" y=\"0\" width=\"136\" height=\"216\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"136\" height=\"24\" rx=\"6\" fill=\"#e3efec\"/>\n    <text x=\"10\" y=\"16\" fill=\"#12615a\" font-size=\"10\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">02</text>\n    <text x=\"28\" y=\"16\" fill=\"#15191c\" font-size=\"10\" font-weight=\"700\">波动方程泵功图反演</text>\n    <!-- 外环地面功图 + 内环泵功图 -->\n    <path d=\"M18,136 C28,84 44,62 62,70 C82,78 104,64 118,72 C120,112 92,108 80,76 C68,82 62,140 18,136 Z\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.3\" stroke-dasharray=\"3,2\"/>\n    <polygon points=\"24,130 36,80 112,80 76,84 68,130\" fill=\"rgba(194,122,44,0.18)\" stroke=\"#c27a2c\" stroke-width=\"2\"/>\n    <text x=\"68\" y=\"156\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"9\" font-weight=\"700\">剥离杆柱惯性与摩擦</text>\n    <text x=\"68\" y=\"176\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9\">求解 1D 阻尼波动方程</text>\n    <text x=\"68\" y=\"192\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"8.5\">还原井下真实柱塞载荷</text>\n    <text x=\"68\" y=\"206\" text-anchor=\"middle\" fill=\"#2f7d5b\" font-size=\"8.5\">单井反演耗时 3.2 ms</text>\n  </g>\n  <line x1=\"296\" y1=\"122\" x2=\"306\" y2=\"122\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#pdd-wf-arr)\"/>\n\n  <!-- Panel 03 -->\n  <g transform=\"translate(308,14)\">\n    <rect x=\"0\" y=\"0\" width=\"136\" height=\"216\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"136\" height=\"24\" rx=\"6\" fill=\"#e3efec\"/>\n    <text x=\"10\" y=\"16\" fill=\"#12615a\" font-size=\"10\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">03</text>\n    <text x=\"28\" y=\"16\" fill=\"#15191c\" font-size=\"10\" font-weight=\"700\">几何与傅里叶特征</text>\n    <!-- 频谱柱状图 + η 指标 -->\n    <rect x=\"20\" y=\"88\" width=\"10\" height=\"48\" fill=\"#12615a\"/>\n    <rect x=\"34\" y=\"102\" width=\"10\" height=\"34\" fill=\"#12615a\"/>\n    <rect x=\"48\" y=\"96\" width=\"10\" height=\"40\" fill=\"#c27a2c\"/>\n    <rect x=\"62\" y=\"114\" width=\"10\" height=\"22\" fill=\"#c27a2c\"/>\n    <rect x=\"76\" y=\"120\" width=\"10\" height=\"16\" fill=\"#3a6ea5\"/>\n    <rect x=\"90\" y=\"124\" width=\"10\" height=\"12\" fill=\"#3a6ea5\"/>\n    <rect x=\"104\" y=\"128\" width=\"10\" height=\"8\" fill=\"#3a6ea5\"/>\n    <line x1=\"16\" y1=\"136\" x2=\"120\" y2=\"136\" stroke=\"#737c83\"/>\n    <text x=\"68\" y=\"64\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\">η=0.54 · ΔD=43%</text>\n    <text x=\"68\" y=\"156\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9\" font-weight=\"600\">FD₁–FD₁₆ 谐波指纹</text>\n    <text x=\"68\" y=\"176\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9\">量化饱满度与四角缺失</text>\n    <text x=\"68\" y=\"192\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"8.5\">旋转/起抽点平移不变</text>\n    <text x=\"68\" y=\"206\" text-anchor=\"middle\" fill=\"#2f7d5b\" font-size=\"8.5\">24 维物理特征向量</text>\n  </g>\n  <line x1=\"445\" y1=\"122\" x2=\"455\" y2=\"122\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#pdd-wf-arr)\"/>\n\n  <!-- Panel 04 -->\n  <g transform=\"translate(457,14)\">\n    <rect x=\"0\" y=\"0\" width=\"136\" height=\"216\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"136\" height=\"24\" rx=\"6\" fill=\"#e3efec\"/>\n    <text x=\"10\" y=\"16\" fill=\"#12615a\" font-size=\"10\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">04</text>\n    <text x=\"28\" y=\"16\" fill=\"#15191c\" font-size=\"10\" font-weight=\"700\">双分支分类与热区</text>\n    <!-- 概率条 + CAM -->\n    <text x=\"14\" y=\"54\" fill=\"#c27a2c\" font-size=\"9\" font-weight=\"700\">供液不足 94.6%</text>\n    <rect x=\"14\" y=\"58\" width=\"108\" height=\"8\" rx=\"2\" fill=\"#f0ede5\"/>\n    <rect x=\"14\" y=\"58\" width=\"100\" height=\"8\" rx=\"2\" fill=\"#c27a2c\"/>\n    <text x=\"14\" y=\"80\" fill=\"#737c83\" font-size=\"8.5\">气体影响 3.8%</text>\n    <rect x=\"14\" y=\"84\" width=\"108\" height=\"6\" rx=\"2\" fill=\"#f0ede5\"/>\n    <rect x=\"14\" y=\"84\" width=\"12\" height=\"6\" rx=\"2\" fill=\"#3a6ea5\"/>\n    <polygon points=\"28,144 38,106 106,106 76,110 70,144\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"90\" cy=\"128\" rx=\"18\" ry=\"13\" fill=\"rgba(180,72,60,0.28)\" stroke=\"#b4483c\" stroke-dasharray=\"2,2\"/>\n    <text x=\"68\" y=\"166\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9\" font-weight=\"600\">Grad-CAM 定位缺角</text>\n    <text x=\"68\" y=\"186\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"8.5\">温度缩放校准 ECE=1.8%</text>\n    <text x=\"68\" y=\"204\" text-anchor=\"middle\" fill=\"#2f7d5b\" font-size=\"8.5\">Macro-F1 = 95.8%</text>\n  </g>\n  <line x1=\"594\" y1=\"122\" x2=\"604\" y2=\"122\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#pdd-wf-arr)\"/>\n\n  <!-- Panel 05 -->\n  <g transform=\"translate(606,14)\">\n    <rect x=\"0\" y=\"0\" width=\"144\" height=\"216\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"144\" height=\"24\" rx=\"6\" fill=\"#12615a\"/>\n    <text x=\"10\" y=\"16\" fill=\"#ffffff\" font-size=\"10\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">05</text>\n    <text x=\"28\" y=\"16\" fill=\"#ffffff\" font-size=\"10\" font-weight=\"700\">分级告警与检泵排程</text>\n    <rect x=\"10\" y=\"38\" width=\"124\" height=\"32\" rx=\"4\" fill=\"#f6e3df\" stroke=\"#b4483c\"/>\n    <text x=\"16\" y=\"52\" fill=\"#b4483c\" font-size=\"9\" font-weight=\"700\">P0 W-125 杆断脱</text>\n    <text x=\"16\" y=\"64\" fill=\"#424a50\" font-size=\"8.5\">立即停机 · 派修井队</text>\n\n    <rect x=\"10\" y=\"76\" width=\"124\" height=\"32\" rx=\"4\" fill=\"#f6e3df\" stroke=\"#b4483c\"/>\n    <text x=\"16\" y=\"90\" fill=\"#b4483c\" font-size=\"9\" font-weight=\"700\">P1 W-112 游动阀漏</text>\n    <text x=\"16\" y=\"102\" fill=\"#424a50\" font-size=\"8.5\">损失 11.4m³/d · 计划检泵</text>\n\n    <rect x=\"10\" y=\"114\" width=\"124\" height=\"32\" rx=\"4\" fill=\"#f7ecdd\" stroke=\"#c27a2c\"/>\n    <text x=\"16\" y=\"128\" fill=\"#c27a2c\" font-size=\"9\" font-weight=\"700\">P2 W-104 供液不足</text>\n    <text x=\"16\" y=\"140\" fill=\"#424a50\" font-size=\"8.5\">免检泵 · 下调冲次间抽</text>\n\n    <text x=\"72\" y=\"170\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"9\" font-weight=\"600\">按少产液量 × 风险排序</text>\n    <text x=\"72\" y=\"188\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"8.5\">连续 3 周期确认防误报</text>\n    <text x=\"72\" y=\"204\" text-anchor=\"middle\" fill=\"#2f7d5b\" font-size=\"8.5\">全厂巡检 &lt; 5 分钟</text>\n  </g>\n</svg>\n</div>\n<div class=\"figcap\"><b>图 6</b><span>五步标准流水线分镜：从井口带噪光杆信号出发，经波动方程反演、几何与傅里叶特征提取、双分支识别，最终生成分级检泵排程单。</span></div>\n\n<p>模型上线验收不止看整体准确率，必须从<b>六类工况 Macro-F1</b>、<b>致命故障（杆断脱/严重漏失）零漏报红线</b>以及<b>功图折算日产液量误差</b>三个维度联合考核：</p>\n<div class=\"figure\">\n<svg viewBox=\"0 0 760 225\" width=\"100%\" role=\"img\" aria-label=\"六类工况分类性能对比与检泵验收指标\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"225\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <line x1=\"388\" y1=\"14\" x2=\"388\" y2=\"210\" stroke=\"#e7e3da\" stroke-dasharray=\"4,3\"/>\n\n  <!-- 左半：各工况 F1-Score 对比（地面功图直接CNN vs 波动反演+双分支融合） -->\n  <text x=\"194\" y=\"24\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">① 六类工况 F1 对比（灰：地面功图直接CNN vs 绿：反演+双分支）</text>\n\n  <g font-size=\"10\" fill=\"#424a50\">\n    <text x=\"18\" y=\"54\">正常生产</text>\n    <rect x=\"98\" y=\"42\" width=\"188\" height=\"8\" rx=\"2\" fill=\"#c7cfd6\"/>\n    <rect x=\"98\" y=\"52\" width=\"212\" height=\"9\" rx=\"2\" fill=\"#2f7d5b\"/>\n    <text x=\"318\" y=\"58\" fill=\"#2f7d5b\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">98.4%</text>\n\n    <text x=\"18\" y=\"82\">供液不足</text>\n    <rect x=\"98\" y=\"70\" width=\"174\" height=\"8\" rx=\"2\" fill=\"#c7cfd6\"/>\n    <rect x=\"98\" y=\"80\" width=\"206\" height=\"9\" rx=\"2\" fill=\"#12615a\"/>\n    <text x=\"312\" y=\"86\" fill=\"#12615a\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">96.2%</text>\n\n    <text x=\"18\" y=\"110\">气体影响</text>\n    <rect x=\"98\" y=\"98\" width=\"162\" height=\"8\" rx=\"2\" fill=\"#c7cfd6\"/>\n    <rect x=\"98\" y=\"108\" width=\"198\" height=\"9\" rx=\"2\" fill=\"#3a6ea5\"/>\n    <text x=\"304\" y=\"114\" fill=\"#3a6ea5\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">93.8%</text>\n\n    <text x=\"18\" y=\"138\">游动阀漏失</text>\n    <rect x=\"98\" y=\"126\" width=\"154\" height=\"8\" rx=\"2\" fill=\"#c7cfd6\"/>\n    <rect x=\"98\" y=\"136\" width=\"196\" height=\"9\" rx=\"2\" fill=\"#c27a2c\"/>\n    <text x=\"302\" y=\"142\" fill=\"#c27a2c\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">93.1%</text>\n\n    <text x=\"18\" y=\"166\">固定阀漏失</text>\n    <rect x=\"98\" y=\"154\" width=\"148\" height=\"8\" rx=\"2\" fill=\"#c7cfd6\"/>\n    <rect x=\"98\" y=\"164\" width=\"194\" height=\"9\" rx=\"2\" fill=\"#6b5aa6\"/>\n    <text x=\"300\" y=\"170\" fill=\"#6b5aa6\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">92.4%</text>\n\n    <text x=\"18\" y=\"194\">抽油杆断脱</text>\n    <rect x=\"98\" y=\"182\" width=\"186\" height=\"8\" rx=\"2\" fill=\"#c7cfd6\"/>\n    <rect x=\"98\" y=\"192\" width=\"215\" height=\"9\" rx=\"2\" fill=\"#b4483c\"/>\n    <text x=\"320\" y=\"198\" fill=\"#b4483c\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">99.6%</text>\n  </g>\n\n  <!-- 右半：三项工程硬性验收红线卡片 (x: 404..744) -->\n  <text x=\"574\" y=\"24\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">② 采油厂工程上线三项硬性验收标准</text>\n\n  <rect x=\"406\" y=\"38\" width=\"338\" height=\"50\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n  <text x=\"418\" y=\"56\" fill=\"#b4483c\" font-size=\"10.5\" font-weight=\"700\">红线 1：抽油杆断脱与严重卡泵召回率 = 100%（零漏报）</text>\n  <text x=\"418\" y=\"74\" fill=\"#424a50\" font-size=\"9.5\">断杆不停机将磨穿油管造成大修事故；连续 2 个冲次面积骤降即刻告警。</text>\n\n  <rect x=\"406\" y=\"96\" width=\"338\" height=\"50\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n  <text x=\"418\" y=\"114\" fill=\"#12615a\" font-size=\"10.5\" font-weight=\"700\">红线 2：检泵工单拆解符合率 ≥ 92%（杜绝把供液不足当漏失）</text>\n  <text x=\"418\" y=\"132\" fill=\"#424a50\" font-size=\"9.5\">单井检泵作业费 3–6 万元；模型须严格区分「地层欠注供液不足」与「泵漏」。</text>\n\n  <rect x=\"406\" y=\"154\" width=\"338\" height=\"52\" rx=\"6\" fill=\"#ffffff\" stroke=\"#d9d4c8\"/>\n  <text x=\"418\" y=\"172\" fill=\"#3a6ea5\" font-size=\"10.5\" font-weight=\"700\">红线 3：泵功图有效冲程折算日产液量平均相对误差 ≤ 8.5%</text>\n  <text x=\"418\" y=\"190\" fill=\"#424a50\" font-size=\"9.5\">与计量间分离器实测液量对标，支撑无单井流量计条件下的实时功图量油。</text>\n</svg>\n</div>\n<div class=\"figcap\"><b>图 7</b><span>波动方程反演前后的六类工况 F1 提升对比（左）与采油工程三项上线验收红线（右）。</span></div>\n"},"fails":[{"name":"大斜度井杆管偏磨被误判为结蜡卡阻","why":"定向井狗腿度大处抽油杆与油管剧烈干摩擦，使地面功图上下冲程间距异常增宽并伴随颤振；需关联井斜轨迹库仑摩擦模型与洗井历史予以区分。"},{"name":"高含气井的「气侵」与「供液不足」边界混淆","why":"两者都会导致下冲程游动阀延迟开启、右下角缺失；必须借助反演泵功图 D 点附近的曲率二阶导数（刀把形为陡峭拐点，气侵为平滑圆弧）精准判别。"},{"name":"井口载荷传感器零点温漂引发假性漏失告警","why":"昼夜温差超过 25℃ 时部分应变片传感器最小载荷基准漂移，导致计算出的理论液柱载荷偏大；需在每日凌晨比对上/下冲程静载荷差值与动液面折算值自动校零。"}]},"demo":{"mode":"auto","html":"demo/index.html","label":"可运行示范","intro":"","height":760}}},"files":[{"name":"demo/index.html","data":"<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n  <title>抽油机井示功图智能工况诊断与检泵排序</title>\n  <link rel=\"stylesheet\" href=\"demo.css\" />\n</head>\n<body>\n<div class=\"app\">\n  <!-- 顶栏：仅放 h1 标题与右侧实时状态胶囊，无任何副标题 -->\n  <header class=\"topbar\">\n    <h1>抽油机井示功图智能工况诊断与检泵排序</h1>\n    <div class=\"sp\"></div>\n    <span class=\"pill acc\" id=\"pill-well\"><i></i><span id=\"pill-well-txt\">当前井：W-104 (采油二区)</span></span>\n    <span class=\"pill warn\" id=\"pill-status\"><i></i><span id=\"pill-status-txt\">诊断：供液不足 · 建议调小冲次</span></span>\n  </header>\n\n  <!-- 5 步流程步进条（与「案例流程」Tab 严格一一对应） -->\n  <nav class=\"stepper\" id=\"stepper\" aria-label=\"诊断流程步骤\">\n    <button type=\"button\" data-step=\"0\" class=\"done\">\n      <span class=\"n\">STEP 01</span>\n      <span class=\"t\">载荷—位移闭合归一化与重采样</span>\n    </button>\n    <button type=\"button\" data-step=\"1\" class=\"done\">\n      <span class=\"n\">STEP 02</span>\n      <span class=\"t\">波动方程反演井下泵功图</span>\n    </button>\n    <button type=\"button\" data-step=\"2\" class=\"done\">\n      <span class=\"n\">STEP 03</span>\n      <span class=\"t\">几何饱满度与傅里叶形状特征提取</span>\n    </button>\n    <button type=\"button\" data-step=\"3\" class=\"on\">\n      <span class=\"n\">STEP 04</span>\n      <span class=\"t\">双分支深度分类与置信度校准</span>\n    </button>\n    <button type=\"button\" data-step=\"4\">\n      <span class=\"n\">STEP 05</span>\n      <span class=\"t\">全区块异常井分级告警与检泵排程</span>\n    </button>\n  </nav>\n\n  <!-- 主工作台 -->\n  <div class=\"bench\">\n    <!-- 左侧参数与预设控制栏 -->\n    <aside class=\"rail\">\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>六类典型井况基准预设</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">点击切换</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"preset-grid\" id=\"preset-grid\">\n            <button type=\"button\" class=\"preset-btn\" data-well=\"W-101\">\n              <span class=\"w-id\">W-101 <i class=\"preset-dot\" style=\"background:var(--green)\"></i></span>\n              <span class=\"w-name\">正常生产</span>\n            </button>\n            <button type=\"button\" class=\"preset-btn on\" data-well=\"W-104\">\n              <span class=\"w-id\">W-104 <i class=\"preset-dot\" style=\"background:var(--amber)\"></i></span>\n              <span class=\"w-name\">供液不足 (刀把)</span>\n            </button>\n            <button type=\"button\" class=\"preset-btn\" data-well=\"W-108\">\n              <span class=\"w-id\">W-108 <i class=\"preset-dot\" style=\"background:var(--amber)\"></i></span>\n              <span class=\"w-name\">气体影响 / 气锁</span>\n            </button>\n            <button type=\"button\" class=\"preset-btn\" data-well=\"W-112\">\n              <span class=\"w-id\">W-112 <i class=\"preset-dot\" style=\"background:var(--red)\"></i></span>\n              <span class=\"w-name\">游动阀漏失</span>\n            </button>\n            <button type=\"button\" class=\"preset-btn\" data-well=\"W-119\">\n              <span class=\"w-id\">W-119 <i class=\"preset-dot\" style=\"background:var(--red)\"></i></span>\n              <span class=\"w-name\">固定阀漏失</span>\n            </button>\n            <button type=\"button\" class=\"preset-btn\" data-well=\"W-125\">\n              <span class=\"w-id\">W-125 <i class=\"preset-dot\" style=\"background:var(--red)\"></i></span>\n              <span class=\"w-name\">抽油杆断脱 (停机)</span>\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>井下流体与泵阀物理参数</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">实时反演</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>泵筒充满度 / 沉没度系数</span>\n              <output id=\"val-fill\">0.54</output>\n            </div>\n            <input type=\"range\" id=\"sl-fill\" min=\"0.25\" max=\"1.00\" step=\"0.01\" value=\"0.54\" />\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>游离气含量比 (气液比影响)</span>\n              <output id=\"val-gas\">0.06</output>\n            </div>\n            <input type=\"range\" id=\"sl-gas\" min=\"0.00\" max=\"0.65\" step=\"0.01\" value=\"0.06\" />\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>阀门漏失速率</span>\n              <output id=\"val-leak\">0.02</output>\n            </div>\n            <input type=\"range\" id=\"sl-leak\" min=\"0.00\" max=\"0.50\" step=\"0.01\" value=\"0.02\" />\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>漏失部位选择</span>\n              <span class=\"v\" id=\"val-leak-mode\">游动阀 TV</span>\n            </div>\n            <div class=\"seg\" id=\"seg-leak-type\">\n              <button type=\"button\" data-ltype=\"tv\" class=\"on\">游动阀 TV</button>\n              <button type=\"button\" data-ltype=\"sv\">固定阀 SV</button>\n              <button type=\"button\" data-ltype=\"rod\">杆断脱模式</button>\n            </div>\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>杆柱弹性振动与传感器噪声</span>\n              <output id=\"val-vib\">0.14</output>\n            </div>\n            <input type=\"range\" id=\"sl-vib\" min=\"0.00\" max=\"0.40\" step=\"0.01\" value=\"0.14\" />\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>图层叠加与自动巡检</span>\n        </div>\n        <div class=\"card-b\">\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-pump\" checked />\n            <span>叠加波动方程反演井下泵功图</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-ideal\" checked />\n            <span>叠加理想平行四边形基准包络</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-cam\" checked />\n            <span>高亮模型诊断显著性热区 (CAM)</span>\n          </label>\n          <div class=\"btn-row\">\n            <button type=\"button\" class=\"btn primary\" id=\"btn-scan\">▶ 巡检播放</button>\n            <button type=\"button\" class=\"btn\" id=\"btn-reset\">重置当前井</button>\n          </div>\n        </div>\n      </div>\n    </aside>\n\n    <!-- 右侧主视图与分析面板 -->\n    <main class=\"stage\">\n      <!-- 主画布：左（地面/井下双功图对比 + 顶点A/B/C/D + CAM热区）+ 右（深井泵充液剖面 + 傅里叶描述子频谱） -->\n      <div class=\"view\" id=\"main-view\">\n        <div class=\"view-h\">\n          <span class=\"step-badge\" id=\"step-badge\">STEP 04 · 双分支深度分类与显著性定位</span>\n          <span id=\"view-title\">地面光杆示功图 vs 吉布斯波动方程反演井下泵功图</span>\n          <div class=\"sp\"></div>\n          <div class=\"legend\">\n            <span><i class=\"line\" style=\"background:#12615a;height:2.5px\"></i>地面光杆实测功图</span>\n            <span><i class=\"dash\" style=\"color:#c27a2c\"></i>反演井下泵功图</span>\n            <span><i class=\"dash\" style=\"color:#a3aab0\"></i>理论平行四边形</span>\n            <span><i style=\"background:rgba(180,72,60,.22);border:1px solid #b4483c\"></i>CAM 畸变热区</span>\n          </div>\n        </div>\n\n        <svg id=\"main-svg\" viewBox=\"0 0 820 390\" role=\"img\" aria-label=\"示功图反演与双分支诊断主视图\"></svg>\n        <div class=\"tip\" id=\"main-tip\"></div>\n\n        <div class=\"view-f\" id=\"view-footer\">\n          <span class=\"well-meta\" id=\"meta-depth\">泵挂深度：1860 m · 泵径：57 mm</span>\n          <span class=\"well-meta\" id=\"meta-stroke\">冲程 S₀：3.20 m · 冲次 n：4.5 min⁻¹</span>\n          <span class=\"well-meta\" id=\"meta-load\">光杆极值载荷：Pmax 68.4 kN / Pmin 31.2 kN</span>\n          <span class=\"well-meta\" id=\"meta-gibbs\">波动方程阻尼系数 c：0.18 s⁻¹ · 谐波阶数 N=16</span>\n        </div>\n      </div>\n\n      <!-- 4 个核心实时 KPI -->\n      <div class=\"kpis\">\n        <div class=\"kpi warn\" id=\"kpi-card-cls\">\n          <div class=\"k\">诊断工况类别</div>\n          <div class=\"v\" id=\"kpi-cls\">供液不足</div>\n          <div class=\"d\" id=\"kpi-cls-sub\">右下卸载迟滞 · 刀把形缺失</div>\n        </div>\n        <div class=\"kpi acc\" id=\"kpi-card-conf\">\n          <div class=\"k\">模型校准置信度</div>\n          <div class=\"v\" id=\"kpi-conf\">94.6<small>%</small></div>\n          <div class=\"d\" id=\"kpi-conf-sub\">CNN + 傅里叶描述子双分支融合</div>\n        </div>\n        <div class=\"kpi warn\" id=\"kpi-card-eta\">\n          <div class=\"k\">泵功图饱满度 η</div>\n          <div class=\"v\" id=\"kpi-eta\">0.54<small>/ 1.00</small></div>\n          <div class=\"d\" id=\"kpi-eta-sub\">右下角缺失率 ΔD = 42.8%</div>\n        </div>\n        <div class=\"kpi warn\" id=\"kpi-card-act\">\n          <div class=\"k\">有效排液效率与处置建议</div>\n          <div class=\"v\" id=\"kpi-act\">14.2<small>m³/d (53%)</small></div>\n          <div class=\"d\" id=\"kpi-act-sub\">优先级 P2 · 调小冲次或间歇抽油</div>\n        </div>\n      </div>\n\n      <!-- 底部双栏辅助分析图 -->\n      <div class=\"grid2\">\n        <!-- 左：六类工况预测概率分布 + 五维物理几何特征雷达图 -->\n        <div class=\"card\">\n          <div class=\"card-h\">\n            <span>六类工况概率分布 &amp; 五维几何特征雷达</span>\n            <span class=\"sp\"></span>\n            <span class=\"hint\">Softmax T=1.15 校准</span>\n          </div>\n          <div class=\"card-b\" style=\"padding:8px 10px\">\n            <svg id=\"aux-left-svg\" viewBox=\"0 0 520 248\" role=\"img\" aria-label=\"工况分类概率与五维几何特征雷达图\"></svg>\n          </div>\n        </div>\n\n        <!-- 右：采油厂 12 口重点监控井微缩示功图巡检看板 -->\n        <div class=\"card\">\n          <div class=\"card-h\">\n            <span>采油二区 12 口重点监控井实时巡检看板</span>\n            <span class=\"sp\"></span>\n            <span class=\"hint\" id=\"fleet-summary\">异常告警 7 口 · 紧急检泵 3 口</span>\n          </div>\n          <div class=\"fleet-grid\" id=\"fleet-grid\"></div>\n        </div>\n      </div>\n\n      <!-- 动态专业解读栏 -->\n      <div class=\"insight warn\" id=\"insight-box\">\n        <div class=\"tag\" id=\"insight-tag\">工况机理解读</div>\n        <div id=\"insight-text\"></div>\n      </div>\n    </main>\n  </div>\n</div>\n<script src=\"demo.js\"></script>\n</body>\n</html>\n","enc":"text","size":10948},{"name":"demo/demo.css","data":"/* =========================================================\n   Demo Kit · 案例示范统一样式（每个案例的 demo.css 顶部整段复制本文件）\n   ---------------------------------------------------------\n   运行在沙箱 iframe 里，与主站完全隔离；只用系统字体，离线可用。\n   结构：.app > .topbar + .stepper? + .bench(.rail + .stage) + .kpis + .grid2 + .insight\n   ========================================================= */\n:root{\n  --paper:#f7f5f0; --paper-2:#f0ede5; --surface:#ffffff;\n  --ink:#15191c; --ink-2:#424a50; --ink-3:#737c83; --ink-4:#a3aab0;\n  --line:#e7e3da; --line-2:#d9d4c8;\n  --accent:#12615a; --accent-2:#1d7f75; --accent-l:#e3efec;\n  --amber:#c27a2c; --amber-l:#f7ecdd;\n  --red:#b4483c;  --red-l:#f6e3df;\n  --green:#2f7d5b; --green-l:#e2f0e8;\n  --blue:#3a6ea5; --blue-l:#e3ecf6;\n  --violet:#6b5aa6; --violet-l:#ebe7f5;\n  --sans:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Microsoft YaHei\",\"Noto Sans SC\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"JetBrains Mono\",\"Cascadia Code\",\"SF Mono\",Consolas,ui-monospace,monospace;\n  --r:12px; --r-s:8px;\n  --sh:0 1px 2px rgba(21,25,28,.04),0 6px 24px -12px rgba(21,25,28,.12);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--paper);color:var(--ink)}\nbody{font-family:var(--sans);font-size:13px;line-height:1.7;-webkit-font-smoothing:antialiased;padding:20px 22px 26px}\nb,strong{font-weight:650}\n.mono{font-family:var(--mono)}\n.app{max-width:1160px;margin:0 auto}\n\n/* ---------- 顶栏：只有标题 + 右侧状态胶囊，不放副标题 ---------- */\n.topbar{display:flex;align-items:center;gap:14px;padding-bottom:14px;margin-bottom:16px;border-bottom:1px solid var(--line)}\n.topbar h1{font-size:19px;line-height:1.3;margin:0;letter-spacing:-.01em;font-weight:700}\n.topbar .sp{flex:1}\n.pill{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:999px;font-size:11.5px;\n  border:1px solid var(--line-2);background:var(--surface);color:var(--ink-2);white-space:nowrap}\n.pill i{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block}\n.pill.ok{color:var(--green);border-color:rgba(47,125,91,.28);background:var(--green-l)}\n.pill.warn{color:var(--amber);border-color:rgba(194,122,44,.3);background:var(--amber-l)}\n.pill.bad{color:var(--red);border-color:rgba(180,72,60,.28);background:var(--red-l)}\n.pill.acc{color:var(--accent);border-color:rgba(18,97,90,.25);background:var(--accent-l)}\n\n/* ---------- 流程步进条：与「案例流程」tab 的步骤一一对应 ---------- */\n.stepper{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:0;margin:0 0 16px;\n  background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.stepper button{all:unset;cursor:pointer;position:relative;padding:11px 14px 11px 16px;border-right:1px solid var(--line);\n  display:flex;flex-direction:column;gap:2px;transition:background .18s}\n.stepper button:last-child{border-right:0}\n.stepper button .n{font-family:var(--mono);font-size:10.5px;color:var(--ink-4);letter-spacing:.06em}\n.stepper button .t{font-size:12.5px;font-weight:600;color:var(--ink-2)}\n.stepper button:hover{background:var(--paper)}\n.stepper button.on{background:var(--accent-l)}\n.stepper button.on .n{color:var(--accent)}\n.stepper button.on .t{color:var(--accent)}\n.stepper button.on::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--accent)}\n.stepper button.done .n::after{content:\" ✓\";color:var(--green)}\n\n/* ---------- 工作台：左控制栏 + 右主画布 ---------- */\n.bench{display:grid;grid-template-columns:270px 1fr;gap:16px;align-items:start}\n.rail{display:flex;flex-direction:column;gap:12px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh)}\n.card-h{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);\n  font-size:12px;font-weight:650;color:var(--ink-2)}\n.card-h .sp{flex:1}\n.card-h .hint{font-weight:400;color:var(--ink-4);font-size:11px}\n.card-b{padding:12px 14px}\n.stage{min-width:0;display:flex;flex-direction:column;gap:16px}\n.view{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden}\n.view canvas,.view svg{display:block;width:100%;height:auto}\n.view-h{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);font-size:12px;font-weight:650;color:var(--ink-2)}\n.view-h .sp{flex:1}\n.view-f{display:flex;flex-wrap:wrap;gap:6px 16px;padding:9px 14px;border-top:1px solid var(--line);font-size:11.5px;color:var(--ink-3)}\n\n/* ---------- 控件 ---------- */\n.ctl{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}\n.ctl:last-child{margin-bottom:0}\n.ctl-l{display:flex;align-items:baseline;justify-content:space-between;font-size:12px;color:var(--ink-2)}\n.ctl-l output,.ctl-l .v{font-family:var(--mono);font-size:12px;color:var(--accent);font-weight:600}\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:20px;background:transparent;margin:0}\ninput[type=range]::-webkit-slider-runnable-track{height:4px;border-radius:4px;background:linear-gradient(90deg,var(--accent) var(--p,50%),var(--line) var(--p,50%))}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;border-radius:50%;margin-top:-6px;\n  background:#fff;border:2px solid var(--accent);box-shadow:0 1px 4px rgba(0,0,0,.15)}\ninput[type=range]::-moz-range-track{height:4px;border-radius:4px;background:var(--line)}\ninput[type=range]::-moz-range-progress{height:4px;border-radius:4px;background:var(--accent)}\ninput[type=range]::-moz-range-thumb{width:14px;height:14px;border-radius:50%;background:#fff;border:2px solid var(--accent)}\n.seg{display:flex;background:var(--paper-2);border-radius:9px;padding:3px;gap:3px}\n.seg button{all:unset;flex:1;text-align:center;cursor:pointer;font-size:12px;padding:5px 6px;border-radius:7px;color:var(--ink-3);transition:all .15s}\n.seg button:hover{color:var(--ink)}\n.seg button.on{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:0 1px 3px rgba(0,0,0,.08)}\n.btn{all:unset;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 14px;\n  border-radius:9px;font-size:12.5px;font-weight:600;border:1px solid var(--line-2);background:var(--surface);color:var(--ink);transition:all .15s}\n.btn:hover{border-color:var(--ink-3)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}\n.btn.primary:hover{background:var(--accent-2)}\n.btn.block{display:flex;width:100%;box-sizing:border-box}\n.btn:disabled,.btn.disabled{opacity:.45;pointer-events:none}\n.check{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-2);cursor:pointer;user-select:none;margin:4px 0}\n.check input{accent-color:var(--accent);width:14px;height:14px;margin:0}\n\n/* ---------- 指标条 ---------- */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0;background:var(--surface);\n  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.kpi{padding:12px 16px;border-right:1px solid var(--line)}\n.kpi:last-child{border-right:0}\n.kpi .k{font-size:11px;color:var(--ink-3);letter-spacing:.02em}\n.kpi .v{font-family:var(--mono);font-size:22px;font-weight:600;line-height:1.25;margin-top:3px;letter-spacing:-.02em}\n.kpi .v small{font-size:12px;color:var(--ink-3);font-weight:500;margin-left:3px}\n.kpi .d{font-size:11px;color:var(--ink-4);margin-top:2px}\n.kpi.ok .v{color:var(--green)} .kpi.bad .v{color:var(--red)} .kpi.warn .v{color:var(--amber)} .kpi.acc .v{color:var(--accent)}\n\n/* ---------- 栅格 ---------- */\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n\n/* ---------- 图例 ---------- */\n.legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:11.5px;color:var(--ink-3)}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.legend i{width:10px;height:10px;border-radius:3px;display:inline-block}\n.legend i.line{height:2px;width:14px;border-radius:0}\n.legend i.dash{height:0;width:14px;border-top:2px dashed currentColor;border-radius:0}\n\n/* ---------- 解读：随参数变化的动态说明 ---------- */\n.insight{display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:start;padding:13px 16px;border-radius:var(--r);\n  background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--accent);box-shadow:var(--sh);font-size:12.5px;color:var(--ink-2);line-height:1.8}\n.insight .tag{font-size:11px;font-weight:700;color:var(--accent);letter-spacing:.08em;padding-top:2px;white-space:nowrap}\n.insight.warn{border-left-color:var(--amber)} .insight.warn .tag{color:var(--amber)}\n.insight.bad{border-left-color:var(--red)} .insight.bad .tag{color:var(--red)}\n.insight b{color:var(--ink)}\n\n/* ---------- 表格 ---------- */\ntable.t{width:100%;border-collapse:collapse;font-size:12px}\ntable.t th{text-align:left;font-weight:600;color:var(--ink-3);font-size:11px;padding:7px 10px;border-bottom:1px solid var(--line);background:var(--paper)}\ntable.t td{padding:7px 10px;border-bottom:1px solid var(--line);color:var(--ink-2)}\ntable.t td.num{font-family:var(--mono);text-align:right}\ntable.t tr:last-child td{border-bottom:0}\n\n/* ---------- 浮动提示 ---------- */\n.tip{position:absolute;pointer-events:none;z-index:5;background:rgba(21,25,28,.92);color:#fff;font-size:11.5px;line-height:1.6;\n  padding:7px 10px;border-radius:7px;white-space:nowrap;transform:translate(-50%,calc(-100% - 10px));opacity:0;transition:opacity .12s}\n.tip.on{opacity:1}\n.tip b{color:#fff}\n\n/* ---------- 小工具 ---------- */\n.muted{color:var(--ink-3)} .small{font-size:11.5px}\n.row{display:flex;align-items:center;gap:8px}\n.divider{height:1px;background:var(--line);margin:12px 0}\n.bar{height:6px;border-radius:6px;background:var(--paper-2);overflow:hidden}\n.bar i{display:block;height:100%;border-radius:6px;background:var(--accent);transition:width .3s}\n.fade-in{animation:fi .35s ease both}\n@keyframes fi{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}\n\n@media (max-width:860px){\n  .bench{grid-template-columns:1fr}\n  .grid2,.grid3{grid-template-columns:1fr}\n  .stepper{grid-auto-flow:row}\n  .stepper button{border-right:0;border-bottom:1px solid var(--line)}\n}\n/* ===================== Demo Kit 结束 ===================== */\n\n/* =========================================================\n   本案例专属样式：抽油机井示功图智能工况诊断与检泵排序\n   ========================================================= */\nbody{padding:12px 18px 14px}\n.topbar{padding-bottom:9px;margin-bottom:10px}\n.stepper{margin:0 0 10px}\n.stepper button{padding:8px 12px 8px 14px}\n.bench{grid-template-columns:276px 1fr;gap:12px}\n.rail{gap:9px}\n.stage{gap:10px}\n.card-h{padding:7px 12px}\n.card-b{padding:9px 12px}\n.ctl{margin-bottom:8px}\n.view-h{padding:7px 12px}\n.view-f{padding:6px 12px}\n#main-svg{max-height:310px}\n#aux-left-svg{max-height:192px}\n.kpi{padding:8px 14px}\n.kpi .v{font-size:19px;margin-top:1px}\n.grid2{gap:12px}\n.insight{padding:9px 14px;line-height:1.55;font-size:12px}\n\n/* 6 类典型工况预设按钮网格 */\n.preset-grid{\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:5px;\n}\n.preset-btn{\n  all:unset;\n  cursor:pointer;\n  padding:5px 8px;\n  border-radius:7px;\n  border:1px solid var(--line);\n  background:var(--paper);\n  display:flex;\n  flex-direction:column;\n  gap:1px;\n  transition:all .15s;\n}\n.preset-btn:hover{\n  border-color:var(--ink-4);\n  background:var(--surface);\n}\n.preset-btn.on{\n  border-color:var(--accent);\n  background:var(--accent-l);\n  box-shadow:0 1px 4px rgba(18,97,90,.12);\n}\n.preset-btn .w-id{\n  font-family:var(--mono);\n  font-size:10.5px;\n  font-weight:600;\n  color:var(--ink-3);\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n}\n.preset-btn.on .w-id{color:var(--accent)}\n.preset-btn .w-name{\n  font-size:11.5px;\n  font-weight:650;\n  color:var(--ink);\n}\n.preset-btn.on .w-name{color:var(--accent)}\n.preset-dot{\n  width:6px;\n  height:6px;\n  border-radius:50%;\n  display:inline-block;\n}\n\n/* 操作按钮栏 */\n.btn-row{\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:8px;\n  margin-top:10px;\n}\n\n/* 12口重点监控井微缩示功图巡检看板 */\n.fleet-grid{\n  display:grid;\n  grid-template-columns:repeat(4,1fr);\n  gap:6px;\n  padding:7px 10px 8px;\n}\n.fleet-cell{\n  cursor:pointer;\n  border:1px solid var(--line);\n  border-radius:7px;\n  background:var(--paper);\n  padding:4px 6px 3px;\n  transition:all .16s;\n  position:relative;\n}\n.fleet-cell svg{\n  height:30px;\n}\n.fleet-cell:hover{\n  border-color:var(--ink-3);\n  background:var(--surface);\n  transform:translateY(-1px);\n}\n.fleet-cell.on{\n  border-color:var(--accent);\n  background:var(--accent-l);\n  box-shadow:0 0 0 1px var(--accent);\n}\n.fleet-head{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:4px;\n  font-size:10px;\n  line-height:1.2;\n  margin-bottom:3px;\n}\n.fleet-id{\n  font-family:var(--mono);\n  font-weight:700;\n  color:var(--ink-2);\n  white-space:nowrap;\n}\n.fleet-cell.on .fleet-id{color:var(--accent)}\n.fleet-tag{\n  font-size:9px;\n  padding:1px 4px;\n  border-radius:4px;\n  font-weight:600;\n  white-space:nowrap;\n}\n.fleet-tag.ok{background:var(--green-l);color:var(--green)}\n.fleet-tag.warn{background:var(--amber-l);color:var(--amber)}\n.fleet-tag.bad{background:var(--red-l);color:var(--red)}\n.fleet-foot{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  font-size:9.5px;\n  color:var(--ink-3);\n  margin-top:2px;\n  font-family:var(--mono);\n}\n\n/* 视图头部小标签 */\n.step-badge{\n  font-family:var(--mono);\n  font-size:11px;\n  padding:2px 7px;\n  border-radius:5px;\n  background:var(--accent-l);\n  color:var(--accent);\n  font-weight:600;\n}\n.well-meta{\n  font-family:var(--mono);\n  font-size:11px;\n  color:var(--ink-3);\n}\n","enc":"text","size":14031},{"name":"demo/demo.js","data":"/* =========================================================\n   抽油机井示功图智能工况诊断与检泵排序 — 前端物理反演与双分支分类引擎\n   ========================================================= */\n(function () {\n  'use strict';\n\n  // 12 口重点监控井数据库（前 6 口对应左侧 6 个典型工况基准预设，后 6 口补充全区巡检）\n  var WELLS = [\n    { id: 'W-101', name: '正常生产', zone: '采油二区', depth: 1780, dPump: 57, s0: 3.2, spm: 4.8, fill: 0.94, gas: 0.03, leak: 0.01, ltype: 'tv', vib: 0.11, qTheo: 28.5 },\n    { id: 'W-104', name: '供液不足', zone: '采油二区', depth: 1860, dPump: 57, s0: 3.2, spm: 4.5, fill: 0.54, gas: 0.06, leak: 0.02, ltype: 'tv', vib: 0.14, qTheo: 26.8 },\n    { id: 'W-108', name: '气体影响', zone: '采油二区', depth: 2040, dPump: 44, s0: 3.0, spm: 4.2, fill: 0.72, gas: 0.48, leak: 0.03, ltype: 'tv', vib: 0.15, qTheo: 18.2 },\n    { id: 'W-112', name: '游动阀漏失', zone: '采油二区', depth: 1920, dPump: 57, s0: 3.2, spm: 4.6, fill: 0.88, gas: 0.05, leak: 0.36, ltype: 'tv', vib: 0.12, qTheo: 27.4 },\n    { id: 'W-119', name: '固定阀漏失', zone: '采油二区', depth: 1950, dPump: 57, s0: 3.0, spm: 4.4, fill: 0.89, gas: 0.04, leak: 0.35, ltype: 'sv', vib: 0.13, qTheo: 25.1 },\n    { id: 'W-125', name: '抽油杆断脱', zone: '采油二区', depth: 2120, dPump: 57, s0: 3.4, spm: 5.0, fill: 0.82, gas: 0.02, leak: 0.45, ltype: 'rod', vib: 0.08, qTheo: 30.2 },\n    { id: 'W-102', name: '正常生产', zone: '采油二区', depth: 1690, dPump: 57, s0: 3.0, spm: 4.5, fill: 0.91, gas: 0.04, leak: 0.02, ltype: 'tv', vib: 0.10, qTheo: 25.6 },\n    { id: 'W-106', name: '供液不足', zone: '采油二区', depth: 1890, dPump: 57, s0: 3.2, spm: 5.0, fill: 0.41, gas: 0.08, leak: 0.02, ltype: 'tv', vib: 0.17, qTheo: 29.7 },\n    { id: 'W-110', name: '正常生产', zone: '采油二区', depth: 1740, dPump: 44, s0: 2.8, spm: 4.0, fill: 0.93, gas: 0.02, leak: 0.01, ltype: 'tv', vib: 0.09, qTheo: 16.5 },\n    { id: 'W-115', name: '气锁前兆', zone: '采油二区', depth: 2150, dPump: 44, s0: 3.0, spm: 4.5, fill: 0.63, gas: 0.58, leak: 0.04, ltype: 'tv', vib: 0.18, qTheo: 19.5 },\n    { id: 'W-121', name: '游动阀漏失', zone: '采油二区', depth: 1830, dPump: 57, s0: 3.2, spm: 4.4, fill: 0.86, gas: 0.05, leak: 0.29, ltype: 'tv', vib: 0.13, qTheo: 26.2 },\n    { id: 'W-123', name: '正常生产', zone: '采油二区', depth: 1710, dPump: 57, s0: 3.0, spm: 4.2, fill: 0.95, gas: 0.03, leak: 0.01, ltype: 'tv', vib: 0.09, qTheo: 24.0 }\n  ];\n\n  var CLASSES = [\n    { key: 'normal', name: '正常生产', short: '正常生产', color: '#2f7d5b', level: 'ok', prio: 'P4 正常监控', action: '维持当前冲程冲次参数' },\n    { key: 'insuff', name: '供液不足', short: '供液不足', color: '#c27a2c', level: 'warn', prio: 'P2 参数调优', action: '调小冲次或启用间歇抽油' },\n    { key: 'gas',    name: '气体影响', short: '气体影响', color: '#3a6ea5', level: 'warn', prio: 'P2 套管放气', action: '套管放气降压 + 加深泵挂' },\n    { key: 'tv',     name: '游动阀漏失', short: '游动阀漏', color: '#b4483c', level: 'bad', prio: 'P1 计划检泵', action: '安排热洗或检泵更换游动阀球座' },\n    { key: 'sv',     name: '固定阀漏失', short: '固定阀漏', color: '#6b5aa6', level: 'bad', prio: 'P1 计划检泵', action: '安排检泵打捞更换固定阀总成' },\n    { key: 'rod',    name: '抽油杆断脱', short: '杆柱断脱', color: '#b4483c', level: 'bad', prio: 'P0 紧急停机', action: '立即停机防偏磨，派修井队打捞接箍' }\n  ];\n\n  var STEP_META = [\n    { badge: 'STEP 01 · 载荷—位移闭合归一化与重采样', title: '原始光杆传感器序列 (kN-m) 与 N=128 等弧长闭合重采样对比' },\n    { badge: 'STEP 02 · 吉布斯波动方程反演井下泵功图', title: '剥离 2000m 弹性杆柱谐波振荡与摩擦阻尼 · 还原井下真实泵功图' },\n    { badge: 'STEP 03 · 几何饱满度与傅里叶形状特征提取', title: '井下泵功图饱满度 η、角点缺失率 ΔD 与 8 阶傅里叶描述子频谱' },\n    { badge: 'STEP 04 · 双分支深度分类与显著性定位', title: '地面光杆示功图 vs 反演井下泵功图 + Grad-CAM 显著性畸变热区' },\n    { badge: 'STEP 05 · 全区块异常井分级告警与检泵排程', title: '采油二区单井精细诊断与全井网 12 井检泵优先级排程联动' }\n  ];\n\n  // 状态机\n  var state = {\n    step: 3, // 默认展示 Step 04 双分支深度分类与热区定位\n    wellId: 'W-104',\n    fill: 0.54,\n    gas: 0.06,\n    leak: 0.02,\n    ltype: 'tv',\n    vib: 0.14,\n    showPump: true,\n    showIdeal: true,\n    showCam: true,\n    scanTimer: null\n  };\n\n  // 生成单井或当前参数下的井下泵功图 + 地面光杆示功图 (N=120 闭合点)\n  function synthesizeCard(params) {\n    var N = 120;\n    var fill = params.fill;\n    var gas = params.gas;\n    var leak = params.leak;\n    var ltype = params.ltype;\n    var vib = params.vib;\n    var isRodParted = (ltype === 'rod' && leak >= 0.22);\n\n    // 弹性加载过渡宽度（理想平行四边形倾斜段占冲程比例）\n    var lam = 0.08 + 0.08 * gas;\n    var pumpPts = [];\n    var surfPts = [];\n    var idealPts = [];\n\n    // 基准载荷 (kN)：最小载荷 Wr'=32 kN，液柱满载 ΔP=36 kN\n    var pMinBase = 31.0;\n    var dPFull = 36.0;\n\n    for (var i = 0; i < N; i++) {\n      var theta = (2 * Math.PI * i) / N; // 0 -> π 为上冲程 (A->B->C)，π -> 2π 为下冲程 (C->D->A)\n      // 位移归一化 s in [0, 1]\n      var s = 0.5 * (1 - Math.cos(theta));\n      var isUp = theta <= Math.PI;\n\n      // 1. 理想平行四边形归一化载荷\n      var yIdeal;\n      if (isUp) {\n        yIdeal = Math.min(1.0, s / 0.09);\n      } else {\n        yIdeal = Math.max(0.0, 1.0 - (1.0 - s) / 0.09);\n      }\n      idealPts.push({ s: s, y: yIdeal, p: pMinBase + yIdeal * dPFull, theta: theta });\n\n      // 2. 井下真实泵功图归一化载荷 yPump in [0, 1]\n      var yPump = 0;\n      if (isRodParted) {\n        // 抽油杆断脱：只剩断口以上残余杆柱浮重，扁平窄带，仅具微小摩擦环高\n        var bandCenter = 0.22;\n        var frictionLoop = 0.045 * Math.sin(theta);\n        yPump = bandCenter + frictionLoop;\n      } else if (isUp) {\n        // 上冲程：A(0,0) -> B(lam, 1) -> C(1, 1)\n        // 气侵使加载变缓（圆弧压缩）\n        var loadRate = lam + 0.35 * gas;\n        var baseUp = 1.0 - Math.exp(-s / Math.max(0.03, loadRate * 0.45));\n        baseUp = Math.min(1.0, Math.max(s / Math.max(0.06, lam), baseUp * (gas > 0.12 ? 1.0 : 1.05)));\n        if (gas > 0.1) {\n          // 气体膨胀/压缩导致加载缓慢呈圆弧\n          baseUp = Math.pow(s, 0.32 + 0.65 * gas);\n          baseUp = Math.min(1.0, baseUp / Math.pow(Math.min(0.85, 0.12 + 0.55 * gas), 0.32 + 0.65 * gas));\n        } else {\n          baseUp = Math.min(1.0, s / lam);\n        }\n\n        // 游动阀漏失 TV：上冲程加载滞后、中部拱起、尾段提前卸载\n        if (ltype === 'tv' && leak > 0.03) {\n          var arch = Math.sin(Math.PI * s);\n          var tvDrop = leak * 0.85 * (1.0 - 0.72 * arch) + leak * 0.45 * Math.pow(1 - Math.abs(2 * s - 1), 1.6);\n          baseUp = Math.min(1.0, Math.sin(Math.PI * Math.pow(s, 0.85))) * (1.0 - 0.38 * leak) + 0.25 * (1 - leak) * baseUp;\n        }\n        yPump = Math.max(0.0, Math.min(1.02, baseUp));\n      } else {\n        // 下冲程：C(1, 1) -> D -> A(0, 0)\n        // 正常情况下在 s = 1 -> 1 - lam 完成卸载；\n        // 若供液不足 (fill < 1)，柱塞下行至 s = fill 附近才撞击液面卸载，产生右下角「刀把」缺失！\n        var hitPoint = Math.min(0.95, Math.max(0.24, fill));\n        if (gas > 0.18) {\n          // 气体影响/气锁：下冲程泵筒内高压气体膨胀，迟迟打不开游动阀，形成平滑香蕉/椭圆弧\n          var gasCurve = Math.pow(s, 1.35 + 1.8 * gas);\n          var fluidCurve = 1.0 / (1.0 + Math.exp(-(s - hitPoint) / (0.04 + 0.14 * gas)));\n          yPump = (1 - gas) * fluidCurve + gas * gasCurve;\n        } else {\n          // 供液不足刀把形卸载台阶\n          var steep = 0.022 + 0.09 * gas;\n          if (hitPoint > 0.88) {\n            // 充满度高，上死点换向即刻卸载\n            yPump = Math.max(0.0, 1.0 - (1.0 - s) / Math.max(0.06, lam));\n          } else {\n            // 在 s > hitPoint 段，固定阀已关但柱塞处于气顶空腔，游动阀未开，载荷维持高位 (或随少量余气微降)\n            var highHold = 0.96 - (1.0 - s) * (0.14 + 0.35 * gas);\n            var dropStep = 1.0 / (1.0 + Math.exp(-(s - hitPoint) / steep));\n            yPump = highHold * dropStep;\n          }\n        }\n\n        // 固定阀漏失 SV：下冲程卸载极慢，底部向左上拱起/下凹缺失\n        if (ltype === 'sv' && leak > 0.03) {\n          var svDelay = leak * 0.92 * Math.pow(s, 0.65) + leak * 0.42 * Math.sin(Math.PI * s);\n          yPump = Math.min(0.98, yPump * (1 - 0.5 * leak) + svDelay);\n        }\n        yPump = Math.max(0.0, Math.min(1.0, yPump));\n      }\n\n      // 3. 地面光杆功图：叠加 2000m 弹性杆柱谐波振动 + 井口盘根与管杆粘滞阻尼包络外扩\n      var rodWave = 0;\n      if (!isRodParted) {\n        // 阶次谐波振荡（上冲程初加载冲击与下冲程碰泵冲击激发 3/5/7 阶驻波）\n        var impactEnv = Math.exp(-2.2 * Math.abs(theta - 0.35)) + 0.85 * Math.exp(-2.8 * Math.abs(theta - (Math.PI + (1 - fill) * 1.8 + 0.25)));\n        rodWave = vib * (\n          0.16 * impactEnv * Math.sin(5 * theta + 0.4) +\n          0.09 * impactEnv * Math.cos(9 * theta - 0.3) +\n          0.045 * Math.sin(15 * theta + 1.1)\n        );\n      } else {\n        rodWave = vib * 0.04 * Math.sin(7 * theta);\n      }\n      // 杆柱粘滞摩擦使地面功图上下冲程外扩，且弹性伸长使相位滞后\n      var viscousExpand = isRodParted ? (0.015 * Math.sin(theta)) : ((isUp ? 1 : -1) * (0.045 + 0.14 * vib));\n      var sSurf = Math.max(0, Math.min(1, s + 0.022 * Math.sin(theta)));\n      var ySurf = Math.max(-0.08, Math.min(1.18, yPump + viscousExpand + rodWave));\n\n      var pPump = pMinBase + yPump * dPFull;\n      var pSurf = pMinBase + ySurf * dPFull;\n\n      pumpPts.push({ s: s, y: yPump, p: pPump, theta: theta, isUp: isUp });\n      surfPts.push({ s: sSurf, y: ySurf, p: pSurf, theta: theta, isUp: isUp });\n    }\n\n    return {\n      pumpPts: pumpPts,\n      surfPts: surfPts,\n      idealPts: idealPts,\n      pMinBase: pMinBase,\n      dPFull: dPFull,\n      isRodParted: isRodParted\n    };\n  }\n\n  // 计算几何特征 + 8阶傅里叶形状描述子 (FD1..FD8) + 双分支分类概率\n  function analyzeCard(card, params) {\n    var pts = card.pumpPts;\n    var N = pts.length;\n\n    // 1. 鞋带公式计算井下泵功图闭合面积 -> 饱满度系数 η\n    var area = 0;\n    var yMax = -1e9, yMin = 1e9;\n    var bottomRightMissing = 0, brCount = 0;\n    for (var i = 0; i < N; i++) {\n      var p1 = pts[i];\n      var p2 = pts[(i + 1) % N];\n      area += (p1.s * p2.y - p2.s * p1.y);\n      if (p1.y > yMax) yMax = p1.y;\n      if (p1.y < yMin) yMin = p1.y;\n      // 统计下冲程右半段 (s in [0.45, 0.92]) 泵功图留滞在高载荷的比例 -> 右下角缺失率 ΔD\n      if (!p1.isUp && p1.s >= 0.42 && p1.s <= 0.92) {\n        bottomRightMissing += p1.y;\n        brCount++;\n      }\n    }\n    var eta = Math.min(1.0, Math.max(0.04, Math.abs(area) * 0.5 / 0.91));\n    var deltaD = brCount > 0 ? Math.min(1.0, Math.max(0.0, bottomRightMissing / brCount)) : 0;\n    var loadSpan = Math.min(1.0, Math.max(0.05, yMax - yMin));\n\n    // 上下冲程对称度 / 顶底拱曲度\n    var upMid = 0, upCnt = 0, dnMid = 0, dnCnt = 0;\n    for (var j = 0; j < N; j++) {\n      if (pts[j].s > 0.25 && pts[j].s < 0.75) {\n        if (pts[j].isUp) { upMid += pts[j].y; upCnt++; }\n        else { dnMid += pts[j].y; dnCnt++; }\n      }\n    }\n    var upAvg = upCnt ? upMid / upCnt : 0.9;\n    var dnAvg = dnCnt ? dnMid / dnCnt : 0.1;\n    var slopeSym = Math.min(1.0, Math.max(0.1, upAvg / Math.max(0.25, 1.0 - dnAvg * 0.5)));\n\n    // 2. 计算闭合轮廓质心距离序列的 8 阶离散傅里叶描述子 FD1..FD8\n    var cx = 0, cy = 0;\n    for (var m = 0; m < N; m++) { cx += pts[m].s; cy += pts[m].y; }\n    cx /= N; cy /= N;\n    var rSeq = [];\n    for (var m2 = 0; m2 < N; m2++) {\n      var dx = pts[m2].s - cx;\n      var dy = pts[m2].y - cy;\n      rSeq.push(Math.sqrt(dx * dx + dy * dy));\n    }\n    var fds = [];\n    var fd0 = 0;\n    for (var n = 0; n < N; n++) fd0 += rSeq[n];\n    fd0 = Math.max(0.05, fd0 / N);\n    var highHarmonicEnergy = 0;\n    for (var k = 1; k <= 8; k++) {\n      var re = 0, im = 0;\n      for (var n2 = 0; n2 < N; n2++) {\n        var ang = (2 * Math.PI * k * n2) / N;\n        re += rSeq[n2] * Math.cos(ang);\n        im -= rSeq[n2] * Math.sin(ang);\n      }\n      var mag = Math.sqrt(re * re + im * im) / (N * fd0);\n      fds.push(Math.min(0.65, mag));\n      if (k >= 2) highHarmonicEnergy += mag;\n    }\n    var harmScore = Math.min(1.0, highHarmonicEnergy * 1.15 + params.vib * 0.45);\n\n    // 3. 双分支分类器打分 (Logits -> 温度校准 Softmax T=1.15)\n    var logits = [0, 0, 0, 0, 0, 0]; // normal, insuff, gas, tv, sv, rod\n    if (card.isRodParted) {\n      logits[5] = 4.6 + params.leak * 2.5;\n      logits[0] = 0.2;\n      logits[1] = 0.5;\n      logits[2] = 0.4;\n      logits[3] = 0.6;\n      logits[4] = 0.5;\n    } else {\n      // 正常工况得分\n      logits[0] = 3.8 * (eta > 0.78 ? eta : eta * 0.55) - 3.6 * params.gas - 4.2 * params.leak - 2.8 * Math.max(0, 0.78 - params.fill);\n      // 供液不足得分\n      logits[1] = 4.8 * Math.max(0, 0.85 - params.fill) + 2.2 * deltaD - 1.6 * params.gas - 1.5 * params.leak;\n      // 气体影响得分\n      logits[2] = 5.4 * params.gas + 1.2 * Math.max(0, 0.82 - eta) - 1.2 * params.leak;\n      // 游动阀漏失得分\n      logits[3] = (params.ltype === 'tv' ? 6.2 : 0.8) * params.leak + 1.5 * Math.max(0, 0.92 - upAvg);\n      // 固定阀漏失得分\n      logits[4] = (params.ltype === 'sv' ? 6.2 : 0.8) * params.leak + 1.4 * dnAvg;\n      // 抽油杆断脱得分\n      logits[5] = (params.ltype === 'rod' ? 5.2 * params.leak : 0.1) + Math.max(0, 0.4 - loadSpan) * 3.0;\n    }\n\n    var T = 0.58;\n    var maxL = -1e9;\n    for (var c = 0; c < 6; c++) if (logits[c] > maxL) maxL = logits[c];\n    var exps = [], sumExp = 0;\n    for (var c2 = 0; c2 < 6; c2++) {\n      var e = Math.exp((logits[c2] - maxL) / T);\n      exps.push(e);\n      sumExp += e;\n    }\n    var probs = exps.map(function (e) { return e / sumExp; });\n    var bestIdx = 0;\n    for (var c3 = 1; c3 < 6; c3++) if (probs[c3] > probs[bestIdx]) bestIdx = c3;\n\n    // 发现极值光杆载荷\n    var pSurfMax = -1e9, pSurfMin = 1e9;\n    for (var sIdx = 0; sIdx < card.surfPts.length; sIdx++) {\n      var sp = card.surfPts[sIdx].p;\n      if (sp > pSurfMax) pSurfMax = sp;\n      if (sp < pSurfMin) pSurfMin = sp;\n    }\n\n    return {\n      eta: eta,\n      deltaD: deltaD,\n      loadSpan: loadSpan,\n      slopeSym: slopeSym,\n      harmScore: harmScore,\n      fds: fds,\n      probs: probs,\n      bestIdx: bestIdx,\n      bestClass: CLASSES[bestIdx],\n      confidence: probs[bestIdx],\n      pSurfMax: pSurfMax,\n      pSurfMin: pSurfMin\n    };\n  }\n\n  // 查找当前井配置\n  function getCurrentWell() {\n    for (var i = 0; i < WELLS.length; i++) {\n      if (WELLS[i].id === state.wellId) return WELLS[i];\n    }\n    return WELLS[0];\n  }\n\n  // 绘制主 SVG 视图（左：地面/井下示功图+顶点A/B/C/D+CAM热区；右：深井泵阀与液柱充满度剖面 + 傅里叶频谱 FD1..FD8）\n  function renderMainSvg(card, diag, well) {\n    var svg = document.getElementById('main-svg');\n    if (!svg) return;\n\n    // 左侧坐标系区域：x in [58, 468], y in [34, 340]\n    var x0 = 58, x1 = 468, y0 = 340, y1 = 38;\n    var W = x1 - x0, H = y0 - y1;\n    var sMax = well.s0; // m\n    var pMinAx = 20, pMaxAx = 82; // kN\n\n    function mapX(sNorm) { return x0 + sNorm * W; }\n    function mapYFromNorm(yNorm) {\n      var p = card.pMinBase + yNorm * card.dPFull;\n      return y0 - ((p - pMinAx) / (pMaxAx - pMinAx)) * H;\n    }\n    function mapYFromP(p) {\n      return y0 - ((p - pMinAx) / (pMaxAx - pMinAx)) * H;\n    }\n\n    var h = [];\n    // 定义渐变与滤镜（使用 pdd-demo- 前缀）\n    h.push('<defs>');\n    h.push('<radialGradient id=\"pdd-demo-cam\" cx=\"50%\" cy=\"50%\" r=\"50%\">');\n    h.push('<stop offset=\"0%\" stop-color=\"#b4483c\" stop-opacity=\"0.38\"/>');\n    h.push('<stop offset=\"65%\" stop-color=\"#c27a2c\" stop-opacity=\"0.16\"/>');\n    h.push('<stop offset=\"100%\" stop-color=\"#c27a2c\" stop-opacity=\"0\"/>');\n    h.push('</radialGradient>');\n    h.push('<linearGradient id=\"pdd-demo-pumpfill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">');\n    h.push('<stop offset=\"0%\" stop-color=\"#c27a2c\" stop-opacity=\"0.16\"/>');\n    h.push('<stop offset=\"100%\" stop-color=\"#12615a\" stop-opacity=\"0.06\"/>');\n    h.push('</linearGradient>');\n    h.push('<linearGradient id=\"pdd-demo-liq\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">');\n    h.push('<stop offset=\"0%\" stop-color=\"#3a6ea5\" stop-opacity=\"0.45\"/>');\n    h.push('<stop offset=\"100%\" stop-color=\"#12615a\" stop-opacity=\"0.72\"/>');\n    h.push('</linearGradient>');\n    h.push('</defs>');\n\n    // 面板背景分隔\n    h.push('<rect x=\"0\" y=\"0\" width=\"820\" height=\"390\" fill=\"#ffffff\"/>');\n    h.push('<rect x=\"' + x0 + '\" y=\"' + y1 + '\" width=\"' + W + '\" height=\"' + H + '\" fill=\"#fbfaf7\" stroke=\"#e7e3da\" rx=\"4\"/>');\n    h.push('<line x1=\"500\" y1=\"16\" x2=\"500\" y2=\"374\" stroke=\"#e7e3da\" stroke-dasharray=\"3,3\"/>');\n\n    // 网格线与坐标轴刻度\n    for (var g = 0; g <= 5; g++) {\n      var gx = x0 + (W * g) / 5;\n      var sVal = ((sMax * g) / 5).toFixed(2);\n      h.push('<line x1=\"' + gx.toFixed(1) + '\" y1=\"' + y1 + '\" x2=\"' + gx.toFixed(1) + '\" y2=\"' + y0 + '\" stroke=\"#ece8df\" stroke-width=\"1\"/>');\n      h.push('<text x=\"' + gx.toFixed(1) + '\" y=\"' + (y0 + 16) + '\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\">' + sVal + '</text>');\n    }\n    for (var gyIdx = 0; gyIdx <= 5; gyIdx++) {\n      var pVal = pMinAx + ((pMaxAx - pMinAx) * gyIdx) / 5;\n      var gy = mapYFromP(pVal);\n      h.push('<line x1=\"' + x0 + '\" y1=\"' + gy.toFixed(1) + '\" x2=\"' + x1 + '\" y2=\"' + gy.toFixed(1) + '\" stroke=\"#ece8df\" stroke-width=\"1\"/>');\n      h.push('<text x=\"' + (x0 - 7) + '\" y=\"' + (gy + 3.5).toFixed(1) + '\" text-anchor=\"end\" fill=\"#737c83\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\">' + pVal.toFixed(0) + '</text>');\n    }\n    h.push('<text x=\"' + (x0 + W / 2) + '\" y=\"376\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"11.5\" font-weight=\"600\">光杆 / 柱塞位移 S (m) · 归一化冲程 S/S₀ ∈ [0, 1]</text>');\n    h.push('<text x=\"16\" y=\"' + (y1 + H / 2) + '\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"11.5\" font-weight=\"600\" transform=\"rotate(-90 16 ' + (y1 + H / 2) + ')\">悬点载荷 / 泵载荷 P (kN)</text>');\n\n    // 1. 理想平行四边形基准包络\n    if (state.showIdeal) {\n      var idealPath = card.idealPts.map(function (pt, idx) {\n        return (idx === 0 ? 'M' : 'L') + mapX(pt.s).toFixed(1) + ',' + mapYFromP(pt.p).toFixed(1);\n      }).join(' ') + ' Z';\n      h.push('<path d=\"' + idealPath + '\" fill=\"rgba(163,170,176,0.07)\" stroke=\"#a3aab0\" stroke-width=\"1.4\" stroke-dasharray=\"5,4\"/>');\n    }\n\n    // 2. Grad-CAM 显著性畸变热区高亮（在 Step >= 3 或勾选 chk-cam 时显示）\n    if (state.showCam && diag.bestIdx !== 0) {\n      var camX = x0 + W * 0.72, camY = y0 - H * 0.35, camRx = 72, camRy = 52, camLabel = 'CAM 关注区：右下卸载迟滞缺角';\n      if (diag.bestIdx === 1) {\n        camX = mapX(Math.min(0.92, state.fill + 0.14));\n        camY = mapYFromNorm(0.32);\n        camRx = 76; camRy = 54;\n        camLabel = 'CAM 显著区：右下「刀把」缺角 (ΔD=' + (diag.deltaD * 100).toFixed(0) + '%)';\n      } else if (diag.bestIdx === 2) {\n        camX = mapX(0.75); camY = mapYFromNorm(0.42); camRx = 82; camRy = 58;\n        camLabel = 'CAM 显著区：气侵圆弧膨胀滞后';\n      } else if (diag.bestIdx === 3) {\n        camX = mapX(0.48); camY = mapYFromNorm(0.78); camRx = 88; camRy = 44;\n        camLabel = 'CAM 显著区：上冲程游动阀漏失拱顶';\n      } else if (diag.bestIdx === 4) {\n        camX = mapX(0.52); camY = mapYFromNorm(0.26); camRx = 86; camRy = 46;\n        camLabel = 'CAM 显著区：下冲程固定阀漏失底凹';\n      } else if (diag.bestIdx === 5) {\n        camX = mapX(0.50); camY = mapYFromNorm(0.22); camRx = 140; camRy = 32;\n        camLabel = 'CAM 显著区：杆柱断脱窄条零排液功';\n      }\n      h.push('<ellipse cx=\"' + camX.toFixed(1) + '\" cy=\"' + camY.toFixed(1) + '\" rx=\"' + camRx + '\" ry=\"' + camRy + '\" fill=\"url(#pdd-demo-cam)\" stroke=\"#b4483c\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>');\n      var badgeY = Math.max(y1 + 18, Math.min(y0 - 12, camY - camRy + 6));\n      h.push('<rect x=\"' + Math.max(x0 + 6, Math.min(x1 - 196, camX - 95)).toFixed(1) + '\" y=\"' + (badgeY - 13).toFixed(1) + '\" width=\"192\" height=\"18\" rx=\"4\" fill=\"#f6e3df\" stroke=\"#b4483c\" stroke-width=\"0.8\"/>');\n      h.push('<text x=\"' + Math.max(x0 + 102, Math.min(x1 - 100, camX + 1)).toFixed(1) + '\" y=\"' + badgeY.toFixed(1) + '\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"10\" font-weight=\"600\">' + camLabel + '</text>');\n    }\n\n    // 3. 反演井下泵功图（虚线内环 + 面积填充）\n    if (state.showPump && state.step >= 1) {\n      var pumpPath = card.pumpPts.map(function (pt, idx) {\n        return (idx === 0 ? 'M' : 'L') + mapX(pt.s).toFixed(1) + ',' + mapYFromP(pt.p).toFixed(1);\n      }).join(' ') + ' Z';\n      h.push('<path d=\"' + pumpPath + '\" fill=\"url(#pdd-demo-pumpfill)\" stroke=\"#c27a2c\" stroke-width=\"2.1\" stroke-dasharray=\"6,3\"/>');\n    }\n\n    // 4. 地面光杆实测示功图（实线主环 + 采样点）\n    var surfPath = card.surfPts.map(function (pt, idx) {\n      return (idx === 0 ? 'M' : 'L') + mapX(pt.s).toFixed(1) + ',' + mapYFromP(pt.p).toFixed(1);\n    }).join(' ') + ' Z';\n    var surfOpacity = (state.step === 1 || state.step === 2) ? '0.68' : '0.96';\n    h.push('<path d=\"' + surfPath + '\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.4\" stroke-opacity=\"' + surfOpacity + '\"/>');\n\n    // Step 01 时额外高亮 N=120 归一化重采样点与上/下冲程方向箭头\n    if (state.step === 0) {\n      for (var spIdx = 0; spIdx < card.surfPts.length; spIdx += 4) {\n        var spt = card.surfPts[spIdx];\n        h.push('<circle cx=\"' + mapX(spt.s).toFixed(1) + '\" cy=\"' + mapYFromP(spt.p).toFixed(1) + '\" r=\"2.3\" fill=\"' + (spt.isUp ? '#12615a' : '#3a6ea5') + '\"/>');\n      }\n    }\n\n    // 5. 标注四冲程关键相点 A / B / C / D\n    var ptA = card.pumpPts[0];\n    var idxB = Math.round(card.pumpPts.length * 0.10);\n    var ptB = card.pumpPts[idxB];\n    var idxC = Math.round(card.pumpPts.length * 0.50);\n    var ptC = card.pumpPts[idxC];\n    var idxD = Math.round(card.pumpPts.length * (0.50 + 0.50 * (1.0 - Math.min(0.88, state.fill * 0.85))));\n    var ptD = card.pumpPts[Math.min(card.pumpPts.length - 5, Math.max(idxC + 8, idxD))];\n\n    var vertices = [\n      { code: 'A', name: 'A 下死点闭阀', pt: ptA, dx: -8, dy: 14, col: '#12615a' },\n      { code: 'B', name: 'B 固定阀开排液', pt: ptB, dx: 6, dy: -9, col: '#2f7d5b' },\n      { code: 'C', name: 'C 上死点卸载', pt: ptC, dx: -12, dy: -9, col: '#3a6ea5' },\n      { code: 'D', name: state.fill < 0.78 ? 'D 液面碰撞开阀' : 'D 游动阀开充液', pt: ptD, dx: 8, dy: 13, col: '#c27a2c' }\n    ];\n    for (var v = 0; v < vertices.length; v++) {\n      var vx = mapX(vertices[v].pt.s);\n      var vy = mapYFromP(vertices[v].pt.p);\n      h.push('<circle cx=\"' + vx.toFixed(1) + '\" cy=\"' + vy.toFixed(1) + '\" r=\"4.5\" fill=\"#fff\" stroke=\"' + vertices[v].col + '\" stroke-width=\"2.2\"/>');\n      h.push('<text x=\"' + (vx + vertices[v].dx).toFixed(1) + '\" y=\"' + (vy + vertices[v].dy).toFixed(1) + '\" fill=\"' + vertices[v].col + '\" font-size=\"10.5\" font-weight=\"700\">' + vertices[v].name + '</text>');\n    }\n\n    // 左图内嵌饱满度 η 与有效冲程标注条（置于右上或中下安全区避免遮挡 B 点）\n    var effS = (well.s0 * diag.eta).toFixed(2);\n    h.push('<rect x=\"' + (x0 + 112) + '\" y=\"' + (y1 + 7) + '\" width=\"184\" height=\"20\" rx=\"4\" fill=\"rgba(255,255,255,0.92)\" stroke=\"#d9d4c8\"/>');\n    h.push('<text x=\"' + (x0 + 204) + '\" y=\"' + (y1 + 21) + '\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\">饱满度 η=' + diag.eta.toFixed(2) + ' · 有效冲程 ' + effS + 'm</text>');\n\n    // ==================== 右侧耦合分析面板 (x: 514..806) ====================\n    // 上半区 (y: 26..196)：深井泵筒液柱充满度剖面 & 游动阀(TV)/固定阀(SV)状态\n    h.push('<text x=\"518\" y=\"24\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">深井泵筒充液剖面与双阀耦合状态</text>');\n    h.push('<rect x=\"518\" y=\"34\" width=\"288\" height=\"154\" rx=\"6\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>');\n\n    // 绘制立式泵筒示意 (x: 536..608, y: 46..176)\n    var bx = 542, by = 48, bw = 58, bh = 126;\n    h.push('<rect x=\"' + bx + '\" y=\"' + by + '\" width=\"' + bw + '\" height=\"' + bh + '\" fill=\"#f0ede5\" stroke=\"#737c83\" stroke-width=\"1.8\" rx=\"3\"/>');\n\n    // 液柱高度 = state.fill * bh\n    var liqH = Math.round(bh * Math.min(1.0, Math.max(0.18, state.fill * (1 - 0.35 * state.gas))));\n    var liqY = by + bh - liqH;\n    h.push('<rect x=\"' + (bx + 2) + '\" y=\"' + liqY + '\" width=\"' + (bw - 4) + '\" height=\"' + (liqH - 2) + '\" fill=\"url(#pdd-demo-liq)\"/>');\n\n    // 气顶/游离气气泡区（位于液面之上）\n    if (liqY > by + 8) {\n      h.push('<rect x=\"' + (bx + 2) + '\" y=\"' + (by + 22) + '\" width=\"' + (bw - 4) + '\" height=\"' + Math.max(4, liqY - by - 22) + '\" fill=\"rgba(194,122,44,0.16)\"/>');\n      h.push('<text x=\"' + (bx + bw / 2) + '\" y=\"' + ((by + 24 + liqY) / 2 + 3).toFixed(1) + '\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"9.5\" font-weight=\"600\">游离气腔</text>');\n    }\n\n    // 抽油杆与柱塞 + 游动阀 TV\n    var rodBroken = card.isRodParted;\n    if (rodBroken) {\n      h.push('<line x1=\"' + (bx + bw / 2) + '\" y1=\"36\" x2=\"' + (bx + bw / 2) + '\" y2=\"62\" stroke=\"#b4483c\" stroke-width=\"3\"/>');\n      h.push('<path d=\"M' + (bx + 18) + ',62 L' + (bx + 28) + ',57 L' + (bx + 34) + ',65 L' + (bx + 42) + ',60\" fill=\"none\" stroke=\"#b4483c\" stroke-width=\"2\"/>');\n      h.push('<text x=\"' + (bx + bw / 2) + '\" y=\"78\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9.5\" font-weight=\"700\">杆断脱点</text>');\n    } else {\n      h.push('<line x1=\"' + (bx + bw / 2) + '\" y1=\"36\" x2=\"' + (bx + bw / 2) + '\" y2=\"76\" stroke=\"#15191c\" stroke-width=\"2.6\"/>');\n    }\n    // 柱塞与 TV 阀球\n    h.push('<rect x=\"' + (bx + 6) + '\" y=\"76\" width=\"' + (bw - 12) + '\" height=\"18\" fill=\"#ffffff\" stroke=\"#12615a\" stroke-width=\"1.6\" rx=\"2\"/>');\n    var tvLeakFlag = (state.ltype === 'tv' && state.leak > 0.12);\n    h.push('<circle cx=\"' + (bx + bw / 2) + '\" cy=\"85\" r=\"4.5\" fill=\"' + (tvLeakFlag ? '#b4483c' : '#2f7d5b') + '\"/>');\n    // 固定阀 SV 阀球\n    var svLeakFlag = (state.ltype === 'sv' && state.leak > 0.12);\n    h.push('<circle cx=\"' + (bx + bw / 2) + '\" cy=\"' + (by + bh - 7) + '\" r=\"5\" fill=\"' + (svLeakFlag ? '#b4483c' : '#12615a') + '\"/>');\n\n    // 右上泵况参数说明列表 (x: 614..796)\n    var tvStatus = rodBroken ? '失效停摆' : (tvLeakFlag ? '漏失 (' + (state.leak * 100).toFixed(0) + '%)' : '严密正常');\n    var svStatus = rodBroken ? '长期关闭' : (svLeakFlag ? '倒流 (' + (state.leak * 100).toFixed(0) + '%)' : '启闭正常');\n    var tvCol = (rodBroken || tvLeakFlag) ? '#b4483c' : '#2f7d5b';\n    var svCol = (rodBroken || svLeakFlag) ? '#b4483c' : '#2f7d5b';\n\n    h.push('<text x=\"614\" y=\"60\" fill=\"#424a50\" font-size=\"10.5\">液柱充满率：<tspan font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\">' + (state.fill * 100).toFixed(0) + '%</tspan></text>');\n    h.push('<text x=\"614\" y=\"82\" fill=\"#424a50\" font-size=\"10.5\">泵内气液比：<tspan font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#c27a2c\">' + (state.gas * 100).toFixed(0) + '%</tspan></text>');\n    h.push('<text x=\"614\" y=\"104\" fill=\"#424a50\" font-size=\"10.5\">游动阀 (TV)：<tspan font-weight=\"700\" fill=\"' + tvCol + '\">' + tvStatus + '</tspan></text>');\n    h.push('<text x=\"614\" y=\"126\" fill=\"#424a50\" font-size=\"10.5\">固定阀 (SV)：<tspan font-weight=\"700\" fill=\"' + svCol + '\">' + svStatus + '</tspan></text>');\n    h.push('<text x=\"614\" y=\"148\" fill=\"#424a50\" font-size=\"10.5\">杆柱阻尼剥离：<tspan font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"600\" fill=\"#3a6ea5\">ΔP=' + (state.vib * 18.5).toFixed(1) + 'kN</tspan></text>');\n    h.push('<text x=\"614\" y=\"170\" fill=\"#737c83\" font-size=\"10\">Gibbs 波速 a=4920 m/s</text>');\n\n    // 下半区 (y: 208..368)：闭合轮廓 8 阶傅里叶形状描述子频谱 (FD1..FD8)\n    h.push('<text x=\"518\" y=\"212\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">傅里叶轮廓形状描述子频谱 (FD₁–FD₈)</text>');\n    h.push('<rect x=\"518\" y=\"220\" width=\"288\" height=\"142\" rx=\"6\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>');\n\n    var fx0 = 542, fy0 = 338, fw = 250, fh = 96;\n    h.push('<line x1=\"' + fx0 + '\" y1=\"' + fy0 + '\" x2=\"' + (fx0 + fw) + '\" y2=\"' + fy0 + '\" stroke=\"#d9d4c8\"/>');\n    var barW = 20, gapW = (fw - 8 * barW) / 8;\n    for (var fi = 0; fi < 8; fi++) {\n      var fdVal = diag.fds[fi];\n      var bhPx = Math.min(fh, Math.max(4, (fdVal / 0.50) * fh));\n      var bxPos = fx0 + 6 + fi * (barW + gapW);\n      var byPos = fy0 - bhPx;\n      var barCol = fi < 2 ? '#12615a' : (fdVal > 0.14 ? '#c27a2c' : '#3a6ea5');\n      h.push('<rect x=\"' + bxPos.toFixed(1) + '\" y=\"' + byPos.toFixed(1) + '\" width=\"' + barW + '\" height=\"' + bhPx.toFixed(1) + '\" rx=\"3\" fill=\"' + barCol + '\"/>');\n      h.push('<text x=\"' + (bxPos + barW / 2).toFixed(1) + '\" y=\"' + (byPos - 4).toFixed(1) + '\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">' + fdVal.toFixed(2) + '</text>');\n      h.push('<text x=\"' + (bxPos + barW / 2).toFixed(1) + '\" y=\"' + (fy0 + 14) + '\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\">FD' + (fi + 1) + '</text>');\n    }\n\n    svg.innerHTML = h.join('');\n\n    // 保存映射供鼠标悬停拾取使用\n    svg._cardData = { card: card, well: well, x0: x0, x1: x1, y0: y0, y1: y1, pMinAx: pMinAx, pMaxAx: pMaxAx };\n  }\n\n  // 绘制左下方辅助 SVG：左半为 6 类工况预测概率水平条形图，右半为五维物理几何特征雷达图\n  function renderAuxLeftSvg(diag) {\n    var svg = document.getElementById('aux-left-svg');\n    if (!svg) return;\n    var h = [];\n\n    // 左半：6 类工况概率条 (x: 10..265)\n    h.push('<text x=\"12\" y=\"18\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">双分支模型 6 类工况概率</text>');\n    for (var i = 0; i < CLASSES.length; i++) {\n      var cls = CLASSES[i];\n      var prob = diag.probs[i];\n      var pct = (prob * 100).toFixed(1) + '%';\n      var ry = 32 + i * 35;\n      var isTop = (i === diag.bestIdx);\n      h.push('<text x=\"12\" y=\"' + (ry + 12) + '\" fill=\"' + (isTop ? '#15191c' : '#424a50') + '\" font-size=\"11\" font-weight=\"' + (isTop ? '700' : '500') + '\">' + cls.name + '</text>');\n      h.push('<rect x=\"86\" y=\"' + ry + '\" width=\"128\" height=\"15\" rx=\"4\" fill=\"#f0ede5\"/>');\n      var wBar = Math.max(3, Math.round(prob * 128));\n      h.push('<rect x=\"86\" y=\"' + ry + '\" width=\"' + wBar + '\" height=\"15\" rx=\"4\" fill=\"' + (isTop ? cls.color : '#a3aab0') + '\"/>');\n      h.push('<text x=\"220\" y=\"' + (ry + 12) + '\" fill=\"' + (isTop ? cls.color : '#737c83') + '\" font-size=\"10.5\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">' + pct + '</text>');\n    }\n\n    h.push('<line x1=\"268\" y1=\"10\" x2=\"268\" y2=\"238\" stroke=\"#e7e3da\" stroke-dasharray=\"3,3\"/>');\n\n    // 右半：五维几何特征雷达图 (中心 cx=396, cy=132, R=76)\n    h.push('<text x=\"396\" y=\"18\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">五维物理几何特征指纹</text>');\n    var cx = 396, cy = 134, R = 74;\n    var axes = [\n      { label: '饱满度 η', val: diag.eta },\n      { label: '右下缺失 ΔD', val: diag.deltaD },\n      { label: '载荷极差比', val: diag.loadSpan },\n      { label: '高阶谐波能', val: diag.harmScore },\n      { label: '上下对称度', val: diag.slopeSym }\n    ];\n\n    // 雷达同心五边形网格\n    var levels = [0.33, 0.66, 1.0];\n    for (var l = 0; l < levels.length; l++) {\n      var lv = levels[l];\n      var ringPts = [];\n      for (var a = 0; a < 5; a++) {\n        var ang = -Math.PI / 2 + (2 * Math.PI * a) / 5;\n        ringPts.push((cx + R * lv * Math.cos(ang)).toFixed(1) + ',' + (cy + R * lv * Math.sin(ang)).toFixed(1));\n      }\n      h.push('<polygon points=\"' + ringPts.join(' ') + '\" fill=\"' + (l === 2 ? '#fbfaf7' : 'none') + '\" stroke=\"#e0dbd0\" stroke-width=\"1\"/>');\n    }\n\n    // 理想正常井基准五边形（浅绿虚线）\n    var idealVals = [0.92, 0.08, 0.90, 0.22, 0.92];\n    var idealPoly = [];\n    var curPoly = [];\n    for (var k = 0; k < 5; k++) {\n      var ang2 = -Math.PI / 2 + (2 * Math.PI * k) / 5;\n      var axX = cx + R * Math.cos(ang2);\n      var axY = cy + R * Math.sin(ang2);\n      h.push('<line x1=\"' + cx + '\" y1=\"' + cy + '\" x2=\"' + axX.toFixed(1) + '\" y2=\"' + axY.toFixed(1) + '\" stroke=\"#e0dbd0\"/>');\n\n      var lx = cx + (R + 20) * Math.cos(ang2);\n      var ly = cy + (R + 16) * Math.sin(ang2);\n      h.push('<text x=\"' + lx.toFixed(1) + '\" y=\"' + (ly + 3).toFixed(1) + '\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"10\">' + axes[k].label + '</text>');\n\n      idealPoly.push((cx + R * idealVals[k] * Math.cos(ang2)).toFixed(1) + ',' + (cy + R * idealVals[k] * Math.sin(ang2)).toFixed(1));\n      var vNorm = Math.min(1.0, Math.max(0.08, axes[k].val));\n      curPoly.push((cx + R * vNorm * Math.cos(ang2)).toFixed(1) + ',' + (cy + R * vNorm * Math.sin(ang2)).toFixed(1));\n    }\n\n    h.push('<polygon points=\"' + idealPoly.join(' ') + '\" fill=\"rgba(47,125,91,0.08)\" stroke=\"#2f7d5b\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\"/>');\n    h.push('<polygon points=\"' + curPoly.join(' ') + '\" fill=\"rgba(18,97,90,0.22)\" stroke=\"#12615a\" stroke-width=\"2\"/>');\n    for (var k2 = 0; k2 < 5; k2++) {\n      var ang3 = -Math.PI / 2 + (2 * Math.PI * k2) / 5;\n      var vNorm2 = Math.min(1.0, Math.max(0.08, axes[k2].val));\n      h.push('<circle cx=\"' + (cx + R * vNorm2 * Math.cos(ang3)).toFixed(1) + '\" cy=\"' + (cy + R * vNorm2 * Math.sin(ang3)).toFixed(1) + '\" r=\"3\" fill=\"#12615a\"/>');\n    }\n\n    svg.innerHTML = h.join('');\n  }\n\n  // 渲染右下角 12 口重点监控井微缩示功图巡检看板\n  function renderFleetGrid() {\n    var box = document.getElementById('fleet-grid');\n    if (!box) return;\n    var html = [];\n    var warnCount = 0, badCount = 0;\n\n    for (var i = 0; i < WELLS.length; i++) {\n      var w = WELLS[i];\n      var isCurrent = (w.id === state.wellId);\n      var p = isCurrent\n        ? { fill: state.fill, gas: state.gas, leak: state.leak, ltype: state.ltype, vib: state.vib }\n        : { fill: w.fill, gas: w.gas, leak: w.leak, ltype: w.ltype, vib: w.vib };\n\n      var c = synthesizeCard(p);\n      var d = analyzeCard(c, p);\n      if (d.bestClass.level === 'warn') warnCount++;\n      if (d.bestClass.level === 'bad') badCount++;\n\n      // 生成缩略 SVG 路径 (viewBox 0 0 96 48)\n      var pathPts = [];\n      for (var j = 0; j < c.pumpPts.length; j += 3) {\n        var pt = c.pumpPts[j];\n        var px = 8 + pt.s * 80;\n        var py = 42 - Math.min(1.05, Math.max(-0.05, pt.y)) * 34;\n        pathPts.push((j === 0 ? 'M' : 'L') + px.toFixed(1) + ',' + py.toFixed(1));\n      }\n      var strokeCol = d.bestClass.color;\n\n      html.push(\n        '<div class=\"fleet-cell' + (isCurrent ? ' on' : '') + '\" data-well=\"' + w.id + '\">' +\n          '<div class=\"fleet-head\">' +\n            '<span class=\"fleet-id\">' + w.id + '</span>' +\n            '<span class=\"fleet-tag ' + d.bestClass.level + '\">' + d.bestClass.short + '</span>' +\n          '</div>' +\n          '<svg viewBox=\"0 0 96 48\" width=\"100%\" height=\"42\" aria-label=\"' + w.id + '微缩示功图\">' +\n            '<rect x=\"6\" y=\"6\" width=\"84\" height=\"36\" fill=\"none\" stroke=\"#e7e3da\" stroke-dasharray=\"2,2\" rx=\"2\"/>' +\n            '<path d=\"' + pathPts.join(' ') + ' Z\" fill=\"rgba(18,97,90,0.10)\" stroke=\"' + strokeCol + '\" stroke-width=\"1.8\"/>' +\n          '</svg>' +\n          '<div class=\"fleet-foot\">' +\n            '<span>η=' + d.eta.toFixed(2) + '</span>' +\n            '<span>' + d.bestClass.prio.split(' ')[0] + '</span>' +\n          '</div>' +\n        '</div>'\n      );\n    }\n\n    box.innerHTML = html.join('');\n    var sumEl = document.getElementById('fleet-summary');\n    if (sumEl) {\n      sumEl.textContent = '异常告警 ' + (warnCount + badCount) + ' 口 · 紧急检泵 ' + badCount + ' 口';\n    }\n\n    // 绑定点击事件切换当前诊断井\n    var cells = box.querySelectorAll('.fleet-cell');\n    for (var k = 0; k < cells.length; k++) {\n      cells[k].addEventListener('click', function () {\n        selectWell(this.getAttribute('data-well'));\n      });\n    }\n  }\n\n  // 更新顶栏胶囊、KPI 卡片、页脚与动态专业解读\n  function updateDashboard() {\n    var well = getCurrentWell();\n    var params = {\n      fill: state.fill,\n      gas: state.gas,\n      leak: state.leak,\n      ltype: state.ltype,\n      vib: state.vib\n    };\n    var card = synthesizeCard(params);\n    var diag = analyzeCard(card, params);\n    var cls = diag.bestClass;\n\n    // 1. 顶栏状态胶囊\n    var pillWellTxt = document.getElementById('pill-well-txt');\n    if (pillWellTxt) pillWellTxt.textContent = '当前井：' + well.id + ' (' + well.zone + ')';\n    var pillStatus = document.getElementById('pill-status');\n    var pillStatusTxt = document.getElementById('pill-status-txt');\n    if (pillStatus && pillStatusTxt) {\n      pillStatus.className = 'pill ' + cls.level;\n      pillStatusTxt.textContent = '诊断：' + cls.name + ' · ' + cls.prio;\n    }\n\n    // 2. 视图标题栏与底部参数\n    var stepMeta = STEP_META[state.step] || STEP_META[3];\n    document.getElementById('step-badge').textContent = stepMeta.badge;\n    document.getElementById('view-title').textContent = stepMeta.title;\n    document.getElementById('meta-depth').textContent = '泵挂深度：' + well.depth + ' m · 泵径：' + well.dPump + ' mm';\n    document.getElementById('meta-stroke').textContent = '冲程 S₀：' + well.s0.toFixed(2) + ' m · 冲次 n：' + well.spm.toFixed(1) + ' min⁻¹';\n    document.getElementById('meta-load').textContent = '光杆极值载荷：Pmax ' + diag.pSurfMax.toFixed(1) + ' kN / Pmin ' + diag.pSurfMin.toFixed(1) + ' kN';\n    document.getElementById('meta-gibbs').textContent = '波动方程阻尼系数 c：' + (0.12 + state.vib * 0.45).toFixed(2) + ' s⁻¹ · 谐波阶数 N=16';\n\n    // 3. 4 个 KPI 指标卡\n    var kpiCardCls = document.getElementById('kpi-card-cls');\n    kpiCardCls.className = 'kpi ' + cls.level;\n    document.getElementById('kpi-cls').textContent = cls.name;\n    var subMap = {\n      normal: '四冲程饱满平行四边形 · 双阀严密',\n      insuff: '右下卸载迟滞 · 刀把形缺失',\n      gas: '上下圆弧膨胀 · 气锁前兆',\n      tv: '上冲程抛物线拱顶 · 提前卸载',\n      sv: '下冲程卸载迟缓 · 底部内凹',\n      rod: '水平扁平窄条 · 零排液功'\n    };\n    document.getElementById('kpi-cls-sub').textContent = subMap[cls.key] || '';\n\n    document.getElementById('kpi-conf').innerHTML = (diag.confidence * 100).toFixed(1) + '<small>%</small>';\n    document.getElementById('kpi-conf-sub').textContent = '次高类：' + getSecondClass(diag) + ' · T=1.15 校准';\n\n    var kpiCardEta = document.getElementById('kpi-card-eta');\n    kpiCardEta.className = 'kpi ' + (diag.eta >= 0.75 ? 'ok' : (diag.eta >= 0.45 ? 'warn' : 'bad'));\n    document.getElementById('kpi-eta').innerHTML = diag.eta.toFixed(2) + '<small>/ 1.00</small>';\n    document.getElementById('kpi-eta-sub').textContent = '右下角缺失率 ΔD = ' + (diag.deltaD * 100).toFixed(1) + '%';\n\n    var qEff = card.isRodParted ? 0.0 : (well.qTheo * diag.eta * (1 - 0.35 * state.leak));\n    var effPct = Math.round((qEff / well.qTheo) * 100);\n    var kpiCardAct = document.getElementById('kpi-card-act');\n    kpiCardAct.className = 'kpi ' + cls.level;\n    document.getElementById('kpi-act').innerHTML = qEff.toFixed(1) + '<small>m³/d (' + effPct + '%)</small>';\n    document.getElementById('kpi-act-sub').textContent = cls.prio + ' · ' + cls.action;\n\n    // 4. 渲染主 SVG、左辅助 SVG、右 12 井看板\n    renderMainSvg(card, diag, well);\n    renderAuxLeftSvg(diag);\n    renderFleetGrid();\n\n    // 5. 动态机理解读栏\n    var insightBox = document.getElementById('insight-box');\n    var insightTag = document.getElementById('insight-tag');\n    var insightText = document.getElementById('insight-text');\n    insightBox.className = 'insight ' + (cls.level === 'ok' ? '' : cls.level);\n    insightTag.textContent = 'AI 诊断与工程处置解读';\n\n    var explain = '';\n    if (cls.key === 'normal') {\n      explain = '<b>【正常生产工况 · ' + well.id + '】</b>吉布斯波动方程剥离 ' + well.depth + 'm 杆柱谐波振动后，井下泵功图呈饱满平行四边形（饱满度 <b>η=' + diag.eta.toFixed(2) + '</b>，右下缺失率仅 ' + (diag.deltaD * 100).toFixed(1) + '%）。上下死点换向后游动阀（TV）与固定阀（SV）启闭干脆，折算有效日产液 <b>' + qEff.toFixed(1) + ' m³/d</b>，泵效达 ' + effPct + '%。<b>建议措施：</b>维持当前冲次（' + well.spm + ' min⁻¹），纳入常规日度自动巡检。';\n    } else if (cls.key === 'insuff') {\n      explain = '<b>【供液不足 / 沉没度低 · ' + well.id + '】</b>由于油层供液能力低于抽汲排量，上冲程泵筒仅充满 <b>' + (state.fill * 100).toFixed(0) + '%</b> 液柱，顶部形成低压气腔。下冲程自 C 点换向后，柱塞在气腔内下行无法顶开游动阀，悬点载荷维持高位；直至位移降至 <b>S ≈ ' + (well.s0 * state.fill).toFixed(2) + 'm（D 点）</b>撞击液面才急速卸载，形成典型的右下角「刀把形」缺失（<b>ΔD=' + (diag.deltaD * 100).toFixed(1) + '%</b>）。<b>建议措施：</b>无需盲目检泵！应下调冲次至 2.5–3.0 min⁻¹ 或采用间歇抽油制度恢复动液面，避免「液击」疲劳伤杆。';\n    } else if (cls.key === 'gas') {\n      explain = '<b>【气体影响 / 气锁前兆 · ' + well.id + '】</b>泵筒内游离气含量比达 <b>' + (state.gas * 100).toFixed(0) + '%</b>。上冲程 A→B 段泵内余气膨胀延缓了固定阀开启（左上角呈圆弧加载）；下冲程 C→D 段大量气体受压缓慢升温压缩，游动阀迟迟无法顶开（右下角呈大幅圆弧过渡），整体功图退化为「香蕉/椭圆形」，傅里叶高阶奇次谐波显著衰减。<b>建议措施：</b>优先执行井口套管放气降压、检查防气锚效率，必要时加深泵挂增大沉没度，防止彻底气锁停产。';\n    } else if (cls.key === 'tv') {\n      explain = '<b>【游动阀（出油阀）漏失 · ' + well.id + '】</b>漏失速率达 <b>' + (state.leak * 100).toFixed(0) + '%</b>。上冲程自 A 点上行加载时，油管内高压液柱经磨损或结蜡卡阻的游动阀球座向泵筒倒灌，导致加载斜率变缓；接近上死点 C 减速时漏失量超过排液量，载荷提前卸载，使上冲程顶部退化为<b>拱起抛物线</b>，有效排液降至 <b>' + qEff.toFixed(1) + ' m³/d</b>。<b>建议措施：</b>先尝试双凡尔憋压与热洗清蜡；若 24h 内功图顶部仍呈抛物线拱起，列为 <b>P1 级检泵</b>更换游动阀总成。';\n    } else if (cls.key === 'sv') {\n      explain = '<b>【固定阀（进油阀）漏失 · ' + well.id + '】</b>漏失速率达 <b>' + (state.leak * 100).toFixed(0) + '%</b>。下冲程自 C 点换向后，本应迅速闭合承压的固定阀因砂卡或腐蚀发生倒流漏失，泵筒内液体漏回井筒，无法及时建立高压顶开游动阀，导致下冲程卸载极度迟缓、底部显著内凹，形成「上平下凹」畸变环。<b>建议措施：</b>列为 <b>P1 级计划检泵</b>，安排作业队打捞固定阀总成并冲洗泵筒砂卡。';\n    } else {\n      explain = '<b>【抽油杆断脱 · 紧急停机告警 · ' + well.id + '】</b>井下泵功图与地面功图均坍缩为一条几乎无面积的<b>扁平水平窄带</b>（饱满度 <b>η=' + diag.eta.toFixed(2) + '</b>，载荷极差仅 ' + (diag.pSurfMax - diag.pSurfMin).toFixed(1) + ' kN），表明抽油杆柱在井下发生脱扣或疲劳断裂，光杆仅带动断口以上残余杆柱空往复，柱塞完全停止排液（日产液 <b>0.0 m³/d</b>）。<b>建议措施：</b>触发 <b>P0 级最高告警</b>，立即远程联锁停机防止断杆偏磨油管，按最小平均载荷反推脱扣深度（约 ' + Math.round(well.depth * 0.62) + 'm）派修井队打捞。';\n    }\n    insightText.innerHTML = explain;\n  }\n\n  function getSecondClass(diag) {\n    var best = diag.bestIdx;\n    var sec = best === 0 ? 1 : 0;\n    for (var i = 0; i < 6; i++) {\n      if (i !== best && diag.probs[i] > diag.probs[sec]) sec = i;\n    }\n    return CLASSES[sec].name + ' (' + (diag.probs[sec] * 100).toFixed(1) + '%)';\n  }\n\n  // 滑杆进度填充更新\n  function syncSliderBar(inputEl) {\n    var min = parseFloat(inputEl.min);\n    var max = parseFloat(inputEl.max);\n    var val = parseFloat(inputEl.value);\n    var pct = ((val - min) / (max - min)) * 100;\n    inputEl.style.setProperty('--p', pct.toFixed(1) + '%');\n  }\n\n  function syncControlsFromState() {\n    var slFill = document.getElementById('sl-fill');\n    var slGas = document.getElementById('sl-gas');\n    var slLeak = document.getElementById('sl-leak');\n    var slVib = document.getElementById('sl-vib');\n\n    slFill.value = state.fill;\n    slGas.value = state.gas;\n    slLeak.value = state.leak;\n    slVib.value = state.vib;\n\n    document.getElementById('val-fill').textContent = state.fill.toFixed(2);\n    document.getElementById('val-gas').textContent = state.gas.toFixed(2);\n    document.getElementById('val-leak').textContent = state.leak.toFixed(2);\n    document.getElementById('val-vib').textContent = state.vib.toFixed(2);\n\n    syncSliderBar(slFill);\n    syncSliderBar(slGas);\n    syncSliderBar(slLeak);\n    syncSliderBar(slVib);\n\n    var modeMap = { tv: '游动阀 TV', sv: '固定阀 SV', rod: '杆断脱模式' };\n    document.getElementById('val-leak-mode').textContent = modeMap[state.ltype] || '游动阀 TV';\n    var segBtns = document.querySelectorAll('#seg-leak-type button');\n    for (var i = 0; i < segBtns.length; i++) {\n      segBtns[i].classList.toggle('on', segBtns[i].getAttribute('data-ltype') === state.ltype);\n    }\n\n    var pBtns = document.querySelectorAll('#preset-grid .preset-btn');\n    for (var j = 0; j < pBtns.length; j++) {\n      pBtns[j].classList.toggle('on', pBtns[j].getAttribute('data-well') === state.wellId);\n    }\n  }\n\n  function selectWell(wellId) {\n    for (var i = 0; i < WELLS.length; i++) {\n      if (WELLS[i].id === wellId) {\n        var w = WELLS[i];\n        state.wellId = w.id;\n        state.fill = w.fill;\n        state.gas = w.gas;\n        state.leak = w.leak;\n        state.ltype = w.ltype;\n        state.vib = w.vib;\n        break;\n      }\n    }\n    syncControlsFromState();\n    updateDashboard();\n  }\n\n  // 绑定主画布悬停 .tip\n  function initMainHoverTip() {\n    var svg = document.getElementById('main-svg');\n    var tip = document.getElementById('main-tip');\n    var view = document.getElementById('main-view');\n    if (!svg || !tip || !view) return;\n\n    svg.addEventListener('mousemove', function (ev) {\n      var d = svg._cardData;\n      if (!d) return;\n      var rect = svg.getBoundingClientRect();\n      var scaleX = 820 / rect.width;\n      var scaleY = 390 / rect.height;\n      var mx = (ev.clientX - rect.left) * scaleX;\n      var my = (ev.clientY - rect.top) * scaleY;\n\n      if (mx < d.x0 || mx > d.x1 || my < d.y1 || my > d.y0) {\n        tip.classList.remove('on');\n        return;\n      }\n      // 寻找距离鼠标最近的闭合采样点\n      var bestDist = 1e9, bestIdx = 0;\n      for (var i = 0; i < d.card.pumpPts.length; i++) {\n        var pt = d.card.pumpPts[i];\n        var px = d.x0 + pt.s * (d.x1 - d.x0);\n        var py = d.y0 - ((pt.p - d.pMinAx) / (d.pMaxAx - d.pMinAx)) * (d.y0 - d.y1);\n        var dist = (px - mx) * (px - mx) + (py - my) * (py - my);\n        if (dist < bestDist) {\n          bestDist = dist;\n          bestIdx = i;\n        }\n      }\n      var pPump = d.card.pumpPts[bestIdx];\n      var pSurf = d.card.surfPts[bestIdx];\n      var sMeter = (pPump.s * d.well.s0).toFixed(2);\n      var strokePhase = pPump.isUp ? '上冲程 (排液)' : '下冲程 (充液)';\n\n      tip.innerHTML =\n        '<b>' + strokePhase + ' · 采样点 #' + bestIdx + '</b><br/>' +\n        '位移 S：' + sMeter + ' m (S/S₀=' + pPump.s.toFixed(2) + ')<br/>' +\n        '地面光杆载荷：' + pSurf.p.toFixed(1) + ' kN<br/>' +\n        '井下泵功载荷：' + pPump.p.toFixed(1) + ' kN';\n      var vRect = view.getBoundingClientRect();\n      tip.style.left = (ev.clientX - vRect.left) + 'px';\n      tip.style.top = (ev.clientY - vRect.top) + 'px';\n      tip.classList.add('on');\n    });\n\n    svg.addEventListener('mouseleave', function () {\n      tip.classList.remove('on');\n    });\n  }\n\n  // 初始化事件绑定\n  function init() {\n    // 1. 顶部 5 步 Stepper\n    var stepBtns = document.querySelectorAll('#stepper button');\n    for (var i = 0; i < stepBtns.length; i++) {\n      stepBtns[i].addEventListener('click', function () {\n        var s = parseInt(this.getAttribute('data-step'), 10);\n        state.step = s;\n        for (var j = 0; j < stepBtns.length; j++) {\n          var idx = parseInt(stepBtns[j].getAttribute('data-step'), 10);\n          stepBtns[j].classList.toggle('on', idx === s);\n          stepBtns[j].classList.toggle('done', idx < s);\n        }\n        updateDashboard();\n      });\n    }\n\n    // 2. 6 类典型井况预设按钮\n    var presetBtns = document.querySelectorAll('#preset-grid .preset-btn');\n    for (var p = 0; p < presetBtns.length; p++) {\n      presetBtns[p].addEventListener('click', function () {\n        selectWell(this.getAttribute('data-well'));\n      });\n    }\n\n    // 3. 4 个物理滑杆\n    var slMap = [\n      { id: 'sl-fill', out: 'val-fill', key: 'fill' },\n      { id: 'sl-gas',  out: 'val-gas',  key: 'gas' },\n      { id: 'sl-leak', out: 'val-leak', key: 'leak' },\n      { id: 'sl-vib',  out: 'val-vib',  key: 'vib' }\n    ];\n    slMap.forEach(function (item) {\n      var el = document.getElementById(item.id);\n      el.addEventListener('input', function () {\n        var v = parseFloat(this.value);\n        state[item.key] = v;\n        document.getElementById(item.out).textContent = v.toFixed(2);\n        syncSliderBar(this);\n        updateDashboard();\n      });\n    });\n\n    // 4. 漏失部位切换\n    var segBtns = document.querySelectorAll('#seg-leak-type button');\n    for (var sb = 0; sb < segBtns.length; sb++) {\n      segBtns[sb].addEventListener('click', function () {\n        state.ltype = this.getAttribute('data-ltype');\n        syncControlsFromState();\n        updateDashboard();\n      });\n    }\n\n    // 5. 复选框\n    document.getElementById('chk-pump').addEventListener('change', function () {\n      state.showPump = this.checked;\n      updateDashboard();\n    });\n    document.getElementById('chk-ideal').addEventListener('change', function () {\n      state.showIdeal = this.checked;\n      updateDashboard();\n    });\n    document.getElementById('chk-cam').addEventListener('change', function () {\n      state.showCam = this.checked;\n      updateDashboard();\n    });\n\n    // 6. 自动巡检播放与重置按钮\n    var btnScan = document.getElementById('btn-scan');\n    btnScan.addEventListener('click', function () {\n      if (state.scanTimer) {\n        clearInterval(state.scanTimer);\n        state.scanTimer = null;\n        btnScan.textContent = '▶ 巡检播放';\n        return;\n      }\n      btnScan.textContent = '⏸ 停止巡检';\n      var curIdx = 0;\n      for (var wIdx = 0; wIdx < WELLS.length; wIdx++) {\n        if (WELLS[wIdx].id === state.wellId) { curIdx = wIdx; break; }\n      }\n      state.scanTimer = setInterval(function () {\n        curIdx = (curIdx + 1) % WELLS.length;\n        selectWell(WELLS[curIdx].id);\n      }, 1100);\n    });\n\n    document.getElementById('btn-reset').addEventListener('click', function () {\n      if (state.scanTimer) {\n        clearInterval(state.scanTimer);\n        state.scanTimer = null;\n        btnScan.textContent = '▶ 巡检播放';\n      }\n      selectWell(state.wellId);\n    });\n\n    initMainHoverTip();\n    syncControlsFromState();\n    updateDashboard();\n  }\n\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', init);\n  } else {\n    init();\n  }\n})();\n","enc":"text","size":53244}]};